        ],
        'job_search.ai_suggest' => [
            'de-CH' => 'KI-Suchkriterien vorschlagen', 'fr-CH' => 'Suggérer des critères avec l’IA', 'en-GB' => 'Suggest criteria with AI', 'pt-BR' => 'Sugerir critérios com IA', 'es-MX' => 'Sugerir criterios con IA',
        ],
        'job_search.ai_hint' => [
            'de-CH' => 'Auf Wunsch optimiert die KI nur Suchbegriff und Suchort. Es werden keine Dokumente, Bewerbungen oder Stellenresultate übertragen.', 'fr-CH' => 'Sur demande, l’IA optimise uniquement le terme et le lieu de recherche. Aucun document, dossier de candidature ou résultat d’offre n’est transmis.', 'en-GB' => 'On request, AI optimizes only the search term and location. No documents, applications or job results are sent.', 'pt-BR' => 'Quando solicitado, a IA otimiza apenas o termo e o local de pesquisa. Nenhum documento, candidatura ou resultado de vaga é enviado.', 'es-MX' => 'Cuando se solicita, la IA optimiza solo el término y la ubicación de búsqueda. No se envían documentos, candidaturas ni resultados de ofertas.',
        ],
        'job_search.ai_applied' => [
            'de-CH' => 'Der KI-Vorschlag wurde als deine Suchkriterien übernommen.', 'fr-CH' => 'La proposition de l’IA a été appliquée à tes critères de recherche.', 'en-GB' => 'The AI suggestion has been applied to your search criteria.', 'pt-BR' => 'A sugestão da IA foi aplicada aos seus critérios de pesquisa.', 'es-MX' => 'La sugerencia de IA se aplicó a tus criterios de búsqueda.',
        ],
        'job_search.ai_failed' => [
            'de-CH' => 'Der KI-Vorschlag konnte nicht erstellt werden. Deine bestehenden Suchkriterien bleiben erhalten.', 'fr-CH' => 'La proposition de l’IA n’a pas pu être créée. Tes critères de recherche actuels sont conservés.', 'en-GB' => 'The AI suggestion could not be created. Your existing search criteria were kept.', 'pt-BR' => 'Não foi possível criar a sugestão de IA. Seus critérios de pesquisa atuais foram mantidos.', 'es-MX' => 'No se pudo crear la sugerencia de IA. Se conservaron tus criterios de búsqueda actuales.',
        ],
    ] as $textKey => $translations) {
        if (isset($managedHelpTexts[$textKey])) { continue; }
        $namespace = substr((string) strtok($textKey, '.'), 0, 80);
        $defaultLocale = 'de-CH';
        $stmt = $db->prepare('INSERT INTO ui_text_keys (text_key, namespace, default_locale) VALUES (?, ?, ?) ON DUPLICATE KEY UPDATE namespace=VALUES(namespace), is_active=1');
        $stmt->bind_param('sss', $textKey, $namespace, $defaultLocale);
        $stmt->execute();
        $keyRow = dbOne($db, 'SELECT id FROM ui_text_keys WHERE text_key=?', 's', [$textKey]);
        if ($keyRow) {
            $textKeyId = (int) $keyRow['id'];
            $status = 'approved';
            $stmt = $db->prepare('INSERT INTO ui_text_translations (text_key_id, locale, text_value, status) VALUES (?, ?, ?, ?) ON DUPLICATE KEY UPDATE text_value=VALUES(text_value), status=VALUES(status)');
            foreach ($translations as $locale => $textValue) {
                $stmt->bind_param('isss', $textKeyId, $locale, $textValue, $status);
                $stmt->execute();
            }
        }
    }
} catch (Throwable $exception) {
    error_log('Locale migration failed: ' . $exception->getMessage());
}

try {
    $column = $db->query("SHOW COLUMNS FROM users LIKE 'last_seen_at'")->fetch_assoc();
    if (!$column) {
        $db->query('ALTER TABLE users ADD COLUMN last_seen_at DATETIME NULL AFTER last_login_at');
    }
    $db->query("CREATE TABLE IF NOT EXISTS user_sessions (
        id INT AUTO_INCREMENT PRIMARY KEY,
        user_id INT NOT NULL,
        session_hash CHAR(64) NOT NULL,
        ip_hash CHAR(64) NULL,
        user_agent_hash CHAR(64) NULL,
        first_seen_at DATETIME NOT NULL,
        last_seen_at DATETIME NOT NULL,
        logged_out_at DATETIME NULL,
        UNIQUE KEY uniq_user_session_hash (session_hash),
        KEY idx_user_sessions_user_active (user_id, logged_out_at, last_seen_at)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
} catch (Throwable $exception) {
    // Optionale Laufzeit-Telemetrie darf die App nicht blockieren.
}

function ensureColumn(mysqli $db, string $table, string $column, string $definition, ?string $after = null): void
{
    $escapedTable = str_replace('`', '``', $table);
    $escapedColumn = $db->real_escape_string($column);
    $exists = $db->query("SHOW COLUMNS FROM `{$escapedTable}` LIKE '{$escapedColumn}'")->fetch_assoc();
    if ($exists) {
        return;
    }
    $afterSql = '';
    if ($after !== null) {
        $escapedAfter = $db->real_escape_string($after);
        $afterExists = $db->query("SHOW COLUMNS FROM `{$escapedTable}` LIKE '{$escapedAfter}'")->fetch_assoc();
        if ($afterExists) {
            $afterSql = ' AFTER `' . str_replace('`', '``', $after) . '`';
        }
    }
    $db->query("ALTER TABLE `{$escapedTable}` ADD COLUMN {$definition}{$afterSql}");
}

function modifyColumnWhenMissingValue(mysqli $db, string $table, string $column, string $value, string $definition): void
{
    $escapedTable = str_replace('`', '``', $table);
    $escapedColumn = $db->real_escape_string($column);
    $columnInfo = $db->query("SHOW COLUMNS FROM `{$escapedTable}` LIKE '{$escapedColumn}'")->fetch_assoc();
    if ($columnInfo && strpos((string) $columnInfo['Type'], "'" . $value . "'") === false) {
        $db->query("ALTER TABLE `{$escapedTable}` MODIFY {$definition}");
    }
}

