function applicationWorkflowDateSql(string $alias = 'a'): string
{
    if (!preg_match('/^[a-z][a-z0-9_]*$/i', $alias)) { throw new InvalidArgumentException('Invalid SQL alias'); }
    return "GREATEST(COALESCE({$alias}.created_at,'1000-01-01'),
        COALESCE((SELECT MAX(h.changed_at) FROM application_status_history h WHERE h.application_id={$alias}.id),'1000-01-01'),
        COALESCE(CASE WHEN {$alias}.status NOT IN ('draft','ready') THEN {$alias}.applied_at END,'1000-01-01'),
        COALESCE((SELECT MAX(ce.starts_at) FROM calendar_events ce WHERE ce.owner_user_id={$alias}.user_id
            AND ce.application_id={$alias}.id AND ce.status<>'cancelled' AND ce.entry_kind<>'milestone'
            AND (ce.source_type IS NULL OR ce.source_type IN ('workflow_appointment','contact_log')
                OR (ce.source_type='application_next_action' AND ce.title='follow_up'))),'1000-01-01'))";
}

function applicationWorkflowView(array $application): array
{
    $status = (string)($application['status'] ?? 'draft');
    return [
        'status' => applicationStatusOptions()[$status] ?? $status,
        'sent_at' => in_array($status, ['draft','ready'], true) ? null : ($application['applied_at'] ?? null),
        'date' => $application['latest_workflow_at'] ?? $application['created_at'] ?? null,
        'next_task' => match ($status) {
            'draft' => applicationNextActionLabel('review_documents'),
            'ready' => applicationNextActionLabel('send_application'),
            default => '',
        },
    ];
}

function workflowDateTime(string $value): string
{
    $value = str_replace('T', ' ', trim($value));
    if (strlen($value) === 16) { $value .= ':00'; }
    $parsed = DateTimeImmutable::createFromFormat('!Y-m-d H:i:s', $value);
    if (!$parsed || $parsed->format('Y-m-d H:i:s') !== $value) {
        throw new InvalidArgumentException(tr('workflow.invalid_date'));
    }
    return $value;
}

function applicationExportRows(mysqli $db, int $userId): array
{
    return dbAll($db, 'SELECT ' . applicationWorkflowDateSql() . ' latest_workflow_at, a.id, a.status, a.channel,
        a.applied_at, a.application_url, a.reference_number, j.title, c.name company FROM applications a
        JOIN jobs j ON j.id=a.job_id JOIN companies c ON c.id=j.company_id
        WHERE a.user_id=? AND a.deleted_at IS NULL ORDER BY j.title, a.id', 'i', [$userId]);
}

function applicationExportHeaders(): array
{
    return [tr('applications.workflow_date'),tr('jobs.job'),tr('companies.company'),tr('common.status'),tr('applications.channel')];
}

function applicationExportData(array $rows, array $user): array
{
    return array_map(static function(array $row) use ($user): array {
        $workflow = applicationWorkflowView($row);
        return [displayDateTime($workflow['date'], $user, false), $row['title'], $row['company'],
            $workflow['status'], optionLabel(applicationChannelOptions(), $row['channel'])];
    }, $rows);
}

function workflowCalendarRange(string $start, string $end): array
{
    $start = workflowDateTime($start);
    $end = trim($end) === '' ? (new DateTimeImmutable($start))->modify('+30 minutes')->format('Y-m-d H:i:s') : workflowDateTime($end);
    if ($end <= $start) { throw new InvalidArgumentException(tr('workflow.invalid_date')); }
    return [$start, $end];
}

function applicationSentAt(array $old, string $status, ?string $input): ?string
{
    if (in_array($status, ['draft','ready'], true)) { return null; }
    $value = trim((string)$input);
    if ($value !== '') {
        $value = workflowDateTime($value);
        return !empty($old['applied_at']) && substr($value,0,16) === substr($old['applied_at'],0,16) ? $old['applied_at'] : $value;
    }
    return $old['applied_at'] ?: ($status === 'sent' ? date('Y-m-d H:i:s') : null);
}

function applicationChannelOptions(): array
{
    return ['email'=>tr('contact_log.channel.email'),'portal'=>tr('applications.channel.portal'),'website'=>tr('applications.channel.website'),'mail'=>tr('applications.channel.mail'),'referral'=>tr('applications.channel.referral'),'other'=>tr('common.other')];
}

function jobRoomCompanyName(array $row): string
{
    $name = trim((string) ($row['company_name'] ?? ''));
    if ($name !== '' && !empty($row['is_intermediary'])) {
        $name .= ' ' . tr('job_room_helper.intermediary_suffix');
    }
    return $name;
}

function jobRoomApplicationMethod(?string $channel): string
{
    return match ((string) $channel) {
        'email', 'portal', 'website' => tr('job_room_helper.method.electronic'),
        'mail' => tr('job_room_helper.method.letter'),
        default => '',
    };
}

function jobRoomApplicationResult(?string $result, ?string $applicationStatus = null): string
{
    return match ((string) $result) {
        'open' => tr('job_room_helper.result.open'),
        'hired' => tr('job_room_helper.result.hired'),
        'rejected' => tr('job_room_helper.result.rejected'),
        default => match ((string) $applicationStatus) {
            'offer', 'accepted' => tr('job_room_helper.result.hired'),
            'rejected', 'withdrawn', 'closed' => tr('job_room_helper.result.rejected'),
            default => tr('job_room_helper.result.open'),
        },
    };
}

function jobRoomWorkloadLabel(array $row): string
{
    $minRaw = $row['workload_min'] ?? null;
    $maxRaw = $row['workload_max'] ?? null;
    $min = $minRaw !== null && $minRaw !== '' ? (int) $minRaw : null;
    $max = $maxRaw !== null && $maxRaw !== '' ? (int) $maxRaw : null;
    if ($min === null && $max === null) {
        return '100%';
    }
    if ($min === null) {
        $min = $max;
    }
    if ($max === null) {
        $max = $min;
    }
    if ($min === $max) {
        return $min . '%';
    }
    return $min . '% - ' . $max . '%';
}

function jobRoomCountryLabel(?string $countryCode): string
{
    $countryCode = strtoupper(trim((string) $countryCode));
    if ($countryCode === '') {
        return tr('job_room_helper.country.switzerland');
    }
    if ($countryCode === 'CH') {
        return tr('job_room_helper.country.switzerland');
    }
    return countryChoices()[$countryCode] ?? $countryCode;
}

function jobRoomHelperRows(mysqli $db, int $userId, ?string $monthStart = null, ?string $monthEnd = null): array
{
    $where = 'a.user_id=? AND a.deleted_at IS NULL';
    $types = 'i';
    $values = [$userId];
    if ($monthStart !== null && $monthEnd !== null) {
        $where .= ' AND COALESCE(a.applied_at, a.updated_at, a.created_at) >= ? AND COALESCE(a.applied_at, a.updated_at, a.created_at) < ?';
        $types .= 'ss';
        $values[] = $monthStart;
        $values[] = $monthEnd;
    }
    return dbAll(
        $db,
        'SELECT a.id application_id, a.status application_status, a.job_room_result, a.job_room_interview, a.channel, a.applied_at, a.application_url, a.reference_number,
                j.id job_id, j.title job_title, j.source_url, j.employment_type, j.workload_min, j.workload_max,
                c.id company_id, c.name company_name, c.is_intermediary, c.email company_email, c.phone company_phone,
                c.address_line1, c.address_line2, c.postal_code, c.city, c.country_code,
                ct.first_name contact_first_name, ct.last_name contact_last_name, ct.email contact_email,
                ct.phone contact_phone, ct.mobile contact_mobile
         FROM applications a
         JOIN jobs j ON j.id=a.job_id AND j.deleted_at IS NULL
         JOIN companies c ON c.id=j.company_id AND c.deleted_at IS NULL
         LEFT JOIN contacts ct ON ct.id=a.primary_contact_id AND ct.deleted_at IS NULL
         WHERE ' . $where . '
         ORDER BY COALESCE(a.applied_at, a.updated_at, a.created_at) DESC, c.name ASC, j.title ASC',
        $types,
        $values
    );
}

function jobRoomHelperFields(array $row, array $currentUser): array
{
    $contactName = trim((string)($row['contact_first_name'] ?? '') . ' ' . (string)($row['contact_last_name'] ?? ''));
    $postalCity = trim(trim((string)($row['postal_code'] ?? '') . ' ' . (string)($row['city'] ?? '')));
    $onlineLink = trim((string)($row['application_url'] ?? '')) ?: trim((string)($row['source_url'] ?? ''));
    return [
        'job_room_helper.field.date' => !empty($row['applied_at']) ? displayDateTime((string)$row['applied_at'], $currentUser, false) : '',
        'job_room_helper.field.method' => jobRoomApplicationMethod($row['channel'] ?? null),
        'job_room_helper.field.company' => jobRoomCompanyName($row),
        'job_room_helper.field.street' => trim((string)($row['address_line1'] ?? '')),
        'job_room_helper.field.po_box' => trim((string)($row['address_line2'] ?? '')),
        'job_room_helper.field.country' => jobRoomCountryLabel($row['country_code'] ?? null),
        'job_room_helper.field.postal_city' => $postalCity,
        'job_room_helper.field.contact_person' => $contactName,
        'job_room_helper.field.email' => trim((string)($row['contact_email'] ?? '')) ?: trim((string)($row['company_email'] ?? '')),
        'job_room_helper.field.phone' => trim((string)($row['contact_phone'] ?? '')) ?: (trim((string)($row['contact_mobile'] ?? '')) ?: trim((string)($row['company_phone'] ?? ''))),
        'job_room_helper.field.job_title' => trim((string)($row['job_title'] ?? '')),
        'job_room_helper.field.online_form_link' => $onlineLink,
        'job_room_helper.field.rav_assigned' => tr('job_room_helper.value.no'),
        'job_room_helper.field.workload' => jobRoomWorkloadLabel($row),
        'job_room_helper.field.interview' => !empty($row['job_room_interview']) ? tr('job_room_helper.value.yes') : tr('job_room_helper.value.no'),
        'job_room_helper.field.result' => jobRoomApplicationResult($row['job_room_result'] ?? null, $row['application_status'] ?? null),
    ];
}

function calendarEventTypeOptions(): array
{
    return ['task'=>tr('calendar.type.task'),'follow_up'=>tr('calendar.type.follow_up'),'interview'=>tr('calendar.type.interview'),'deadline'=>tr('calendar.type.deadline'),'meeting'=>tr('calendar.type.meeting'),'reminder'=>tr('calendar.type.reminder'),'other'=>tr('common.other')];
}

function calendarStatusOptions(): array
{
    return ['planned'=>tr('calendar.status.planned'),'completed'=>tr('calendar.status.completed'),'cancelled'=>tr('calendar.status.cancelled')];
}

function saveReportSettings(mysqli $db, int $reportId, string $base): void
{
    $db->query('DELETE FROM saved_report_columns WHERE report_id=' . $reportId);
    $db->query('DELETE FROM saved_report_filters WHERE report_id=' . $reportId);
    $db->query('DELETE FROM saved_report_sorts WHERE report_id=' . $reportId);

    $fields = reportFieldOptions($base);
    $columns = array_values(array_filter((array) ($_POST['report_columns'] ?? []), static fn($field): bool => isset($fields[(string)$field])));
    if (!$columns) {
        $columns = reportDefaultColumns($base);
    }
    $columnStmt = $db->prepare('INSERT INTO saved_report_columns (report_id, field_name, label, sort_order, is_visible) VALUES (?, ?, ?, ?, 1)');
    foreach ($columns as $index => $field) {
        $field = (string) $field;
        $label = $fields[$field];
        $order = $index + 1;
        $columnStmt->bind_param('issi', $reportId, $field, $label, $order);
        $columnStmt->execute();
    }

    $filterStmt = $db->prepare('INSERT INTO saved_report_filters (report_id, field_name, operator, value_json, sort_order) VALUES (?, ?, ?, ?, ?)');
    $order = 1;
    $query = trim((string) ($_POST['report_q'] ?? ''));
    if ($query !== '') {
        $field = 'q';
        $operator = 'contains';
        $value = json_encode($query, JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR);
        $filterStmt->bind_param('isssi', $reportId, $field, $operator, $value, $order);
        $filterStmt->execute();
        $order++;
    }
    $status = trim((string) ($_POST['report_status'] ?? ''));
    if ($status !== '' && isset(reportStatusOptions($base)[$status])) {
        $field = 'status';
        $operator = 'eq';
        $value = json_encode($status, JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR);
        $filterStmt->bind_param('isssi', $reportId, $field, $operator, $value, $order);
        $filterStmt->execute();
    }

    $sortField = (string) ($_POST['report_sort'] ?? '');
    if (!isset($fields[$sortField])) {
        $sortField = $columns[0] ?? array_key_first($fields);
    }
    $direction = strtolower((string) ($_POST['report_dir'] ?? 'asc')) === 'desc' ? 'desc' : 'asc';
    $priority = 1;
    $sortStmt = $db->prepare('INSERT INTO saved_report_sorts (report_id, field_name, direction, priority) VALUES (?, ?, ?, ?)');
    $sortStmt->bind_param('issi', $reportId, $sortField, $direction, $priority);
    $sortStmt->execute();
}

function loadReportSettings(mysqli $db, int $reportId, string $base): array
{
    $columns = dbAll($db, 'SELECT field_name, label FROM saved_report_columns WHERE report_id=? AND is_visible=1 ORDER BY sort_order, id', 'i', [$reportId]);
    $filters = dbAll($db, 'SELECT field_name, value_json FROM saved_report_filters WHERE report_id=? ORDER BY sort_order, id', 'i', [$reportId]);
    $sort = dbOne($db, 'SELECT field_name, direction FROM saved_report_sorts WHERE report_id=? ORDER BY priority, id LIMIT 1', 'i', [$reportId]);
    $selected = $columns ? array_map(static fn(array $row): string => (string)$row['field_name'], $columns) : reportDefaultColumns($base);
    $filterValues = [];
    foreach ($filters as $filter) {
        $filterValues[(string)$filter['field_name']] = json_decode((string)$filter['value_json'], true) ?: '';
    }
    return ['columns'=>$selected, 'filters'=>$filterValues, 'sort'=>$sort ?: ['field_name'=>$selected[0] ?? 'title', 'direction'=>'asc']];
}

function reportDataset(mysqli $db, int $userId, array $report, array $settings, array $currentUser): array
{
    $base = (string) ($report['base_entity'] ?? 'jobs');
    $fields = reportFieldOptions($base);
    $requestedColumns = (array)$settings['columns'];
    if ($base === 'applications') {
        $requestedColumns = array_unique(array_map(static fn($field) => in_array($field, ['next_action','next_action_at'], true) ? 'latest_workflow_at' : $field, $requestedColumns));
    }
    $columns = array_values(array_filter($requestedColumns, static fn($field): bool => isset($fields[(string)$field])));
    if (!$columns) {
        $columns = reportDefaultColumns($base);
    }
    $headers = array_map(static fn(string $field): string => $fields[$field], $columns);
    $filters = (array) ($settings['filters'] ?? []);
    $q = strtolower((string) ($filters['q'] ?? ''));
    $status = (string) ($filters['status'] ?? '');

    $rows = match ($base) {
        'applications' => applicationExportRows($db, $userId),
        'companies' => dbAll($db, 'SELECT name, city, website, is_intermediary, updated_at FROM companies WHERE owner_user_id=? AND deleted_at IS NULL', 'i', [$userId]),
        'contacts' => dbAll($db, 'SELECT CONCAT(c.last_name, " ", c.first_name) name, co.name company, c.email, COALESCE(NULLIF(c.phone,""), c.mobile) phone, c.position, c.updated_at, (SELECT COUNT(*) FROM contact_logs l WHERE l.contact_id=c.id AND l.status IN ("open","planned")) open_logs FROM contacts c JOIN companies co ON co.id=c.company_id WHERE c.owner_user_id=? AND c.deleted_at IS NULL', 'i', [$userId]),
        'documents' => dbAll($db, 'SELECT d.title, dt.name_key type, d.original_filename filename, d.scope, d.version, d.created_at FROM user_documents d JOIN document_types dt ON dt.id=d.document_type_id WHERE d.user_id=? AND d.deleted_at IS NULL', 'i', [$userId]),
        'calendar' => calendarEventRows($db, $userId, (new DateTimeImmutable('-30 days'))->setTime(0, 0), (new DateTimeImmutable('+90 days'))->setTime(23, 59, 59)),
        default => dbAll($db, 'SELECT j.title, c.name company, j.location_text location, j.status, j.workplace_type, j.updated_at FROM jobs j JOIN companies c ON c.id=j.company_id WHERE j.owner_user_id=? AND j.deleted_at IS NULL', 'i', [$userId]),
    };

    $rows = array_values(array_filter($rows, static function(array $row) use ($q, $status, $base): bool {
        if ($status !== '') {
            if ($base === 'contacts') {
                $hasOpen = (int)($row['open_logs'] ?? 0) > 0;
                if (($status === 'open' && !$hasOpen) || ($status === 'none' && $hasOpen)) {
                    return false;
                }
            } elseif ((string)($row['status'] ?? '') !== $status) {
                return false;
            }
        }
        if ($q === '') {
            return true;
        }
        return str_contains(strtolower(implode(' ', array_map('strval', $row))), $q);
    }));

    $sort = (array) ($settings['sort'] ?? []);
    $sortField = isset($fields[(string)($sort['field_name'] ?? '')]) ? (string)$sort['field_name'] : ($columns[0] ?? array_key_first($fields));
    $dir = strtolower((string)($sort['direction'] ?? 'asc')) === 'desc' ? 'desc' : 'asc';
    usort($rows, static function(array $a, array $b) use ($sortField, $dir): int {
        $result = strcmp((string)($a[$sortField] ?? ''), (string)($b[$sortField] ?? ''));
        return $dir === 'desc' ? -$result : $result;
    });

    $data = [];
    foreach ($rows as $row) {
        if ($base === 'applications') {
            $workflow = applicationWorkflowView($row);
            $row['applied_at'] = $workflow['sent_at'];
            $row['status'] = $workflow['status'];
            $row['channel'] = optionLabel(applicationChannelOptions(), $row['channel']);
        }
        $data[] = array_map(static function(string $field) use ($row, $currentUser): string {
            $value = $row[$field] ?? '';
            if ($field === 'latest_workflow_at') { return displayDateTime($value ?: null, $currentUser, false); }
            if (in_array($field, ['updated_at','created_at','applied_at','next_action_at','starts_at'], true)) {
                return displayDateTime($value ?: null, $currentUser);
            }
            if ($field === 'is_intermediary') {
                return !empty($value) ? 'Ja' : 'Nein';
            }
            return (string) $value;
        }, $columns);
    }

    return [$headers, $data];
}

function calendarViewOptions(): array
{
    return ['agenda'=>tr('calendar.view.agenda'),'day'=>tr('calendar.view.day'),'workweek'=>tr('calendar.view.workweek'),'week'=>tr('calendar.view.week'),'month'=>tr('calendar.view.month')];
}

function calendarAnchorDate(array $user): DateTimeImmutable
{
    $timezone = new DateTimeZone((string) ($user['timezone'] ?? 'Europe/Zurich'));
    $date = (string) ($_GET['date'] ?? '');
    try {
        return $date !== '' ? new DateTimeImmutable($date, $timezone) : new DateTimeImmutable('today', $timezone);
    } catch (Throwable) {
        return new DateTimeImmutable('today', $timezone);
    }
}

function calendarRange(string $view, DateTimeImmutable $anchor): array
{
    $monthFirst = $anchor->setDate((int) $anchor->format('Y'), (int) $anchor->format('m'), 1)->setTime(0, 0);
    $monthLast = $monthFirst->modify('last day of this month')->setTime(23, 59, 59);
    $monthStart = $monthFirst->modify('-' . ((int) $monthFirst->format('N') - 1) . ' days');
    $monthEnd = $monthLast->modify('+' . (7 - (int) $monthLast->format('N')) . ' days');

    return match ($view) {
        'day' => [$anchor->setTime(0, 0), $anchor->setTime(23, 59, 59), '-1 day', '+1 day'],
        'workweek' => [$anchor->modify('monday this week')->setTime(0, 0), $anchor->modify('friday this week')->setTime(23, 59, 59), '-1 week', '+1 week'],
        'week' => [$anchor->modify('monday this week')->setTime(0, 0), $anchor->modify('sunday this week')->setTime(23, 59, 59), '-1 week', '+1 week'],
        'month' => [$monthStart, $monthEnd, '-1 month', '+1 month'],
        default => [$anchor->setTime(0, 0), $anchor->modify('+60 days')->setTime(23, 59, 59), '-30 days', '+30 days'],
    };
}

function calendarEventRows(mysqli $db, int $userId, DateTimeImmutable $start, DateTimeImmutable $end): array
{
    $startSql = $start->format('Y-m-d H:i:s');
    $endSql = $end->format('Y-m-d H:i:s');
    $rows = [];
    $statusLabels = applicationStatusOptions();
    $nextActionLabels = applicationNextActionOptions();
    foreach (dbAll($db, "SELECT ce.id, ce.title, ce.event_type, ce.entry_kind, ce.source_type, ce.source_id, ce.source_key, ce.starts_at, ce.ends_at, ce.all_day, ce.location, ce.status, ce.notes, ce.application_id, ce.contact_id, a.applied_at, a.status application_status, h.new_status workflow_status, j.title job_title, c.name company_name, ct.first_name, ct.last_name
        FROM calendar_events ce
        LEFT JOIN application_status_history h ON ce.source_type='application_status' AND h.id=ce.source_id
        LEFT JOIN applications a ON a.id=ce.application_id AND a.deleted_at IS NULL
        LEFT JOIN jobs j ON j.id=a.job_id AND j.deleted_at IS NULL
        LEFT JOIN companies c ON c.id=j.company_id AND c.deleted_at IS NULL
        LEFT JOIN contacts ct ON ct.id=ce.contact_id AND ct.deleted_at IS NULL
        WHERE ce.owner_user_id=? AND ce.status<>'cancelled' AND ce.starts_at<=? AND COALESCE(ce.ends_at, ce.starts_at)>=?
        ORDER BY ce.starts_at ASC, ce.id ASC", 'iss', [$userId, $endSql, $startSql]) as $event) {
        $sourceType = (string)($event['source_type'] ?? '');
        $entryKind = (string)($event['entry_kind'] ?? 'appointment');
        $title = (string)$event['title'];
        $type = calendarEventTypeOptions()[(string)$event['event_type']] ?? (string)$event['event_type'];
        $status = calendarStatusOptions()[(string)$event['status']] ?? (string)$event['status'];
        $href = '/?page=calendar&edit_event=' . (int)$event['id'] . '#calendar-entry-form';
        if ($sourceType === 'workflow_appointment' && $title === 'follow_up') { $title = tr('next_action.follow_up'); }
        if (in_array($sourceType, ['application_status', 'application_submission'], true)) {
            $workflowStatus = (string)($event['workflow_status'] ?: $event['source_key']);
            $status = $statusLabels[$workflowStatus] ?? $workflowStatus;
            $title = $workflowStatus === 'sent' ? tr('calendar.application_sent') : $status;
            $type = tr('applications.status_history');
            $href = '/?page=applications&edit=' . (int)$event['application_id'] . '#application-form';
        } elseif (in_array($sourceType, ['application_next_action', 'application_action_done'], true)) {
            $title = $nextActionLabels[$title] ?? $title;
            $type = tr('nav.calendar');
            $href = '/?page=applications&edit=' . (int)$event['application_id'] . '#application-form';
        } elseif ($sourceType === 'contact_log') {
            if ($title === 'follow_up') {
                $title = $nextActionLabels['follow_up'] ?? $title;
            }
            $type = tr('nav.calendar');
            $href = '/?page=contacts&edit_contact=' . (int)$event['contact_id'] . '#contact-log';
        }
        $contactName = trim((string)($event['first_name'] ?? '') . ' ' . (string)($event['last_name'] ?? ''));
        $metaParts = array_filter([(string)($event['job_title'] ?? ''), (string)($event['company_name'] ?? ''), $contactName]);
        $rows[] = [
            'source' => $sourceType !== '' ? 'workflow_event' : 'calendar',
            'id' => (int) $event['id'],
            'entry_kind' => $entryKind,
            'source_type' => $sourceType,
            'source_key' => (string)($event['source_key'] ?? ''),
            'workflow_status' => (string)($event['workflow_status'] ?? $event['source_key'] ?? ''),
            'application_id' => (int)($event['application_id'] ?? 0),
            'raw_title' => (string)$event['title'],
            'applied_at' => (string)($event['applied_at'] ?? ''),
            'application_status' => (string)($event['application_status'] ?? ''),
            'all_day' => (int)$event['all_day'],
            'location' => (string)($event['location'] ?? ''),
            'company_name' => (string)($event['company_name'] ?? ''),
            'job_title' => (string)($event['job_title'] ?? ''),
            'title' => $title,
            'type' => $type,
            'status' => $status,
            'starts_at' => (string) $event['starts_at'],
            'ends_at' => (string) ($event['ends_at'] ?: date('Y-m-d H:i:s', strtotime((string) $event['starts_at']) + 1800)),
            'meta' => implode(' · ', $metaParts),
            'notes' => (string) ($event['notes'] ?? ''),
            'href' => $href,
        ];
    }
    return calendarExportRows($rows);
}

function calendarIcsEscape(string $value): string
{
    return str_replace(["\\", "\r\n", "\n", ",", ";"], ["\\\\", "\\n", "\\n", "\\,", "\\;"], $value);
}

function calendarIcsText(array $events, array $user = []): string
{
    $ics = "BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//JeMa Jobs//Calendar//EN\r\nCALSCALE:GREGORIAN\r\n";
    foreach (calendarExportRows($events) as $event) {
        $times = calendarRemoteTimes($event,$user);
        if (isset($times['start']['date'])) {
            $dates = 'DTSTART;VALUE=DATE:'.str_replace('-','',$times['start']['date'])."\r\nDTEND;VALUE=DATE:".str_replace('-','',$times['end']['date']);
        } else {
            $utc = new DateTimeZone('UTC');
            $dates = 'DTSTART:'.(new DateTimeImmutable($times['start']['dateTime']))->setTimezone($utc)->format('Ymd\THis\Z')
                ."\r\nDTEND:".(new DateTimeImmutable($times['end']['dateTime']))->setTimezone($utc)->format('Ymd\THis\Z');
        }
        $uid = calendarIcsEscape($event['source'].'-'.$event['id'].'@jobs.jema.business');
        $summary = calendarIcsEscape((string)$event['title']);
        $description = calendarIcsEscape(trim((string)($event['meta'] ?? '')."\n".(string)($event['notes'] ?? '')));
        $ics.="BEGIN:VEVENT\r\nUID:{$uid}\r\nDTSTAMP:".gmdate('Ymd\THis\Z')."\r\n{$dates}\r\nSUMMARY:{$summary}\r\nDESCRIPTION:{$description}\r\n";
        if (($event['entry_kind'] ?? '')==='milestone') { $ics.="TRANSP:TRANSPARENT\r\n"; }
        $ics.="END:VEVENT\r\n";
    }
    $ics.="END:VCALENDAR\r\n";
    $folded=[];
    foreach (explode("\r\n",$ics) as $line) {
        $part='';
        foreach (preg_split('//u',$line,-1,PREG_SPLIT_NO_EMPTY) ?: [] as $character) {
            if (strlen($part)+strlen($character)>74) { $folded[]=$part; $part=' '; }
            $part.=$character;
        }
        $folded[]=$part;
    }
    return implode("\r\n",$folded);
}

function calendarIcsResponse(string $filename, array $events, array $user = []): never
{
    $ics=calendarIcsText($events,$user);
    header('Content-Type: text/calendar; charset=utf-8');
    header('Content-Disposition: attachment; filename="'.addslashes($filename).'"');
    header('Content-Length: '.strlen($ics));
    echo $ics;
    exit;
}

function calendarFeedToken(): string
{
    return bin2hex(random_bytes(32));
}

function ensureCalendarFeed(mysqli $db, int $userId): array
{
    $feed = dbOne($db, 'SELECT token, is_active FROM user_calendar_feeds WHERE user_id=? LIMIT 1', 'i', [$userId]);
    if ($feed && (int) $feed['is_active'] === 1 && trim((string) $feed['token']) !== '') {
        return $feed;
    }
    $token = calendarFeedToken();
    if ($feed) {
        $stmt = $db->prepare('UPDATE user_calendar_feeds SET token=?, is_active=1 WHERE user_id=?');
        $stmt->bind_param('si', $token, $userId);
        $stmt->execute();
    } else {
        $stmt = $db->prepare('INSERT INTO user_calendar_feeds (user_id, token, is_active) VALUES (?, ?, 1)');
        $stmt->bind_param('is', $userId, $token);
        $stmt->execute();
    }
    return ['token' => $token, 'is_active' => 1];
}

function rotateCalendarFeed(mysqli $db, int $userId): string
{
    $token = calendarFeedToken();
    $stmt = $db->prepare('INSERT INTO user_calendar_feeds (user_id, token, is_active) VALUES (?, ?, 1) ON DUPLICATE KEY UPDATE token=VALUES(token), is_active=1');
    $stmt->bind_param('is', $userId, $token);
    $stmt->execute();
    return $token;
}

function googleCalendarSettings(mysqli $db, int $userId): array
{
    return dbOne($db, 'SELECT user_id, calendar_id, calendar_summary, access_token_encrypted, refresh_token_encrypted, token_expires_at, sync_enabled, last_sync_at, last_error FROM user_google_calendar_settings WHERE user_id=? LIMIT 1', 'i', [$userId]) ?: [];
}

function googleCalendarAppCredentials(array $config): array
{
    return [
        'client_id' => trim((string) ($config['google_calendar_client_id'] ?? '')),
        'client_secret' => trim((string) ($config['google_calendar_client_secret'] ?? '')),
    ];
}

function googleCalendarIsConfigured(array $config): bool
{
    $credentials = googleCalendarAppCredentials($config);
    return $credentials['client_id'] !== '' && $credentials['client_secret'] !== '';
}

function googleCalendarScope(): string
{
    return 'https://www.googleapis.com/auth/calendar';
}

function googleCalendarRedirectUri(array $config): string
{
    return absoluteUrl($config, '/?page=google_calendar_callback');
}

function googleCalendarAuthUrl(array $config, string $clientId, string $state): string
{
    return 'https://accounts.google.com/o/oauth2/v2/auth?' . http_build_query([
        'client_id' => $clientId,
        'redirect_uri' => googleCalendarRedirectUri($config),
        'response_type' => 'code',
        'scope' => googleCalendarScope(),
        'access_type' => 'offline',
        'prompt' => 'consent',
        'state' => $state,
    ], '', '&', PHP_QUERY_RFC3986);
}

function googleHttpStatus(array $headers): int
{
    foreach ($headers as $header) {
        if (preg_match('~^HTTP/\S+\s+(\d{3})~', (string) $header, $matches)) {
            return (int) $matches[1];
        }
    }
    return 0;
}

function googleJsonRequest(string $method, string $url, array $headers = [], ?array $payload = null): array
{
    $headerLines = array_merge(['Accept: application/json'], $headers);
    $body = '';
    if ($payload !== null) {
        $body = json_encode($payload, JSON_UNESCAPED_UNICODE);
        $headerLines[] = 'Content-Type: application/json; charset=utf-8';
    }
    $context = stream_context_create(['http' => [
        'method' => $method,
        'header' => implode("\r\n", $headerLines),
        'content' => $body,
        'ignore_errors' => true,
        'timeout' => 25,
    ]]);
    $response = @file_get_contents($url, false, $context);
    $responseHeaders = $http_response_header ?? [];
    $status = googleHttpStatus($responseHeaders);
    $data = json_decode((string) $response, true);
    $data = is_array($data) ? $data : [];
    if ($status >= 400 || $response === false) {
        $message = (string) ($data['error']['message'] ?? $data['error_description'] ?? $data['error'] ?? 'Google API error');
        throw new RuntimeException($message, $status);
    }
    return $data;
}

function googleFormRequest(array $params): array
{
    $body = http_build_query($params, '', '&', PHP_QUERY_RFC3986);
    $context = stream_context_create(['http' => [
        'method' => 'POST',
        'header' => "Accept: application/json\r\nContent-Type: application/x-www-form-urlencoded",
        'content' => $body,
        'ignore_errors' => true,
        'timeout' => 25,
    ]]);
    $response = @file_get_contents('https://oauth2.googleapis.com/token', false, $context);
    $responseHeaders = $http_response_header ?? [];
    $status = googleHttpStatus($responseHeaders);
    $data = json_decode((string) $response, true);
    $data = is_array($data) ? $data : [];
    if ($status >= 400 || $response === false) {
        $message = (string) ($data['error_description'] ?? $data['error'] ?? 'Google OAuth error');
        throw new RuntimeException($message);
    }
    return $data;
}

function googleAccessToken(mysqli $db, array $config, int $userId, array $settings): string
{
    $accessToken = decryptSecret($config, $settings['access_token_encrypted'] ?? null);
    $expiresAt = trim((string) ($settings['token_expires_at'] ?? ''));
    if ($accessToken !== '' && ($expiresAt === '' || strtotime($expiresAt) > time() + 120)) {
        return $accessToken;
    }
    $refreshToken = decryptSecret($config, $settings['refresh_token_encrypted'] ?? null);
    $credentials = googleCalendarAppCredentials($config);
    $clientId = $credentials['client_id'];
    $clientSecret = $credentials['client_secret'];
    if ($clientId === '' || $clientSecret === '' || $refreshToken === '') {
        throw new RuntimeException(tr('flash.google_calendar.credentials_required'));
    }
    $tokens = googleFormRequest([
        'client_id' => $clientId,
        'client_secret' => $clientSecret,
        'refresh_token' => $refreshToken,
        'grant_type' => 'refresh_token',
    ]);
    $accessToken = (string) ($tokens['access_token'] ?? '');
    if ($accessToken === '') {
        throw new RuntimeException('Google access token missing');
    }
    $encryptedAccess = encryptSecret($config, $accessToken);
    $expires = date('Y-m-d H:i:s', time() + (int) ($tokens['expires_in'] ?? 3600));
    $stmt = $db->prepare('UPDATE user_google_calendar_settings SET access_token_encrypted=?, token_expires_at=?, updated_at=NOW() WHERE user_id=?');
    $stmt->bind_param('ssi', $encryptedAccess, $expires, $userId);
    $stmt->execute();
    return $accessToken;
}

function googleCalendarStableId(int $userId, string $calendarId, string $source, int $id): string
{
    return hash('sha256', 'jobs.jema.business:' . $userId . ':' . $calendarId . ':' . $source . ':' . $id);
}

function backupGoogleCalendarEvent(mysqli $db, int $userId, string $calendarId, array $event): void
{
    $json = json_encode($event, JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR);
    $key = hash('sha256', $userId . ':' . $calendarId . ':' . $json);
    $eventId = (string)$event['id'];
    cascadeExec($db, 'INSERT IGNORE INTO google_calendar_event_backups (backup_key, user_id, calendar_id, google_event_id, payload) VALUES (?, ?, ?, ?, ?)', 'sisss', [$key, $userId, $calendarId, $eventId, $json]);
}

function googleCalendarOwnsEvent(array $remote, string $source, int $id): bool
{
    $private = $remote['extendedProperties']['private'] ?? [];
    return ($private['jema_source'] ?? '') === $source && (string)($private['jema_id'] ?? '') === (string)$id;
}

function calendarExportRows(array $events): array
{
    $rows = [];
    $seen = [];
    foreach ($events as $event) {
        $source = (string)($event['source_type'] ?? '');
        if ($source === 'application_action_done') { continue; }
        if ($source === 'application_next_action' && ($event['raw_title'] ?? '') !== 'follow_up') { continue; }
        if (in_array($source,['application_status','application_submission'],true) && empty($event['application_id'])) { continue; }
        if ($source === 'application_next_action'
            && preg_match('/^(completed|closed)-[0-9]+$/', (string)($event['source_key'] ?? ''))) { continue; }
        if (($event['entry_kind'] ?? '') === 'milestone') {
            // Preparation and process changes stay in history; they are not appointments.
            $status = (string)($event['workflow_status'] ?? $event['raw_title'] ?? '');
            if (!in_array($status, ['sent', 'accepted', 'rejected'], true)) { continue; }
            if ($status === 'sent' && in_array($event['application_status'] ?? '', ['draft','ready'], true)) { continue; }
            $key = (int)($event['application_id'] ?? 0) . ':' . $status;
            if (!empty($event['application_id']) && isset($seen[$key])) { continue; }
            $seen[$key] = true;
            $event['all_day'] = 0;
            $event['ends_at'] = (new DateTimeImmutable($event['starts_at']))->modify('+1 minute')->format('Y-m-d H:i:s');
        }
        $rows[] = $event;
    }
    return $rows;
}

function calendarRemoteTimes(array $event, array $user): array
{
    $timezone = new DateTimeZone((string)($user['timezone'] ?? 'Europe/Zurich'));
    $start = new DateTimeImmutable((string)$event['starts_at'], $timezone);
    $end = !empty($event['ends_at']) ? new DateTimeImmutable((string)$event['ends_at'], $timezone) : $start;
    if (!empty($event['all_day'])) {
        $start = $start->setTime(0, 0);
        $end = $end->setTime(0, 0);
        if ($end <= $start) {
            $end = $start->modify('+1 day');
        }
        return ['start' => ['date' => $start->format('Y-m-d')], 'end' => ['date' => $end->format('Y-m-d')]];
    }
    if ($end <= $start) {
        $end = $start->modify(($event['entry_kind'] ?? '') === 'milestone' ? '+1 minute' : '+30 minutes');
    }
    return [
        'start' => ['dateTime' => $start->format(DateTimeInterface::RFC3339), 'timeZone' => $timezone->getName()],
        'end' => ['dateTime' => $end->format(DateTimeInterface::RFC3339), 'timeZone' => $timezone->getName()],
    ];
}

function googleCalendarLinkIsCurrent(?array $link, string $hash): bool
{
    return $link !== null && trim((string)($link['google_event_id'] ?? '')) !== ''
        && empty($link['last_error']) && (string)($link['last_hash'] ?? '') === $hash;
}

function syncGoogleCalendarEventsLocked(mysqli $db, array $config, int $userId, array $user): array
{
    if (!dbOne($db, "SELECT migration_key FROM app_migrations WHERE migration_key='workflow_calendar_v6'")) {
        throw new RuntimeException('Calendar migration has not completed; synchronization paused');
    }
    $settings = googleCalendarSettings($db, $userId);
    if (!$settings || !(int) ($settings['sync_enabled'] ?? 0)) {
        throw new RuntimeException(tr('flash.google_calendar.credentials_required'));
    }
    $token = googleAccessToken($db, $config, $userId, $settings);
    $calendarId = trim((string) ($settings['calendar_id'] ?? '')) ?: 'primary';
    $start = (new DateTimeImmutable('-30 days'))->setTime(0, 0);
    $end = (new DateTimeImmutable('+365 days'))->setTime(23, 59, 59);
    $importError = null;
    try {
        $importResult = importGoogleCalendarEvents($db, $token, $calendarId, $userId, $user, $start, $end);
    } catch (Throwable $exception) {
        // Ein fehlgeschlagener Import darf lokale Versandnachweise nicht blockieren.
        $importError = mb_substr($exception->getMessage(), 0, 1000);
        $importResult = ['created' => 0, 'updated' => 0, 'deleted' => 0];
    }
    $importedCalendarIds = array_flip(array_map(static fn(array $row): int => (int) $row['calendar_event_id'], dbAll($db, 'SELECT calendar_event_id FROM google_calendar_import_links WHERE user_id=?', 'i', [$userId])));
    $created = (int) $importResult['created'];
    $updated = (int) $importResult['updated'];
    $failed = $importError !== null ? 1 : 0;
    $exportFailed = 0;
    $range = dbOne($db, "SELECT MIN(starts_at) first_at, MAX(COALESCE(ends_at,starts_at)) last_at FROM calendar_events WHERE owner_user_id=? AND status<>'cancelled'", 'i', [$userId]);
    if (!empty($range['first_at'])) {
        $start = new DateTimeImmutable($range['first_at']);
        $end = new DateTimeImmutable($range['last_at']);
    }
    $activeExports = [];
    foreach (calendarExportRows(calendarEventRows($db, $userId, $start, $end)) as $event) {
        $sourceType = (string) $event['source'];
        $sourceId = (int) $event['id'];
        if ($sourceType === 'calendar' && isset($importedCalendarIds[$sourceId])) {
            continue;
        }
        $activeExports[$sourceType . ':' . $sourceId] = true;
        $hash = googleCalendarSyncHash($event);
        $link = dbOne($db, 'SELECT google_event_id, last_hash, last_error FROM google_calendar_event_links WHERE user_id=? AND source_type=? AND source_id=? LIMIT 1', 'isi', [$userId, $sourceType, $sourceId]);
        if (googleCalendarLinkIsCurrent($link, $hash)) {
            continue;
        }
        $payload = googleCalendarEventPayload($config, $event, $user);
        try {
            $stableId = googleCalendarStableId($userId, $calendarId, $sourceType, $sourceId);
            if (($link['last_hash'] ?? '') === 'retired') {
                // A cancelled legacy projection gets a reproducible replacement ID.
                $stableId = hash('sha256', $stableId . ':timed-v5');
                $googleEventId = $stableId;
            } else {
                $googleEventId = trim((string)($link['google_event_id'] ?? '')) ?: $stableId;
            }
            $baseUrl = 'https://www.googleapis.com/calendar/v3/calendars/' . rawurlencode($calendarId) . '/events';
            $remote = null;
            try {
                $remote = googleJsonRequest('GET', $baseUrl . '/' . rawurlencode($googleEventId), ['Authorization: Bearer ' . $token]);
            } catch (RuntimeException $exception) {
                if (!in_array($exception->getCode(), [404, 410], true)) { throw $exception; }
            }
            if ($remote === null && $googleEventId !== $stableId) {
                $googleEventId = $stableId;
                try {
                    $remote = googleJsonRequest('GET', $baseUrl . '/' . $googleEventId, ['Authorization: Bearer ' . $token]);
                } catch (RuntimeException $exception) {
                    if (!in_array($exception->getCode(), [404, 410], true)) { throw $exception; }
                }
            }
            if ($remote !== null) {
                if (!googleCalendarOwnsEvent($remote, $sourceType, $sourceId)) {
                    throw new RuntimeException('Calendar event ownership mismatch');
                }
                backupGoogleCalendarEvent($db, $userId, $calendarId, $remote);
                $headers = ['Authorization: Bearer ' . $token];
                if (!empty($remote['etag'])) { $headers[] = 'If-Match: ' . $remote['etag']; }
                googleJsonRequest('PATCH', $baseUrl . '/' . rawurlencode($googleEventId), $headers, $payload + ['status' => 'confirmed']);
                $updated++;
            } else {
                $response = googleJsonRequest('POST', $baseUrl, ['Authorization: Bearer ' . $token], $payload + ['id' => $googleEventId]);
                $googleEventId = (string)($response['id'] ?? '');
                $created++;
            }
            if ($googleEventId === '') {
                throw new RuntimeException('Google event id missing');
            }
            $emptyError = null;
            $stmt = $db->prepare('INSERT INTO google_calendar_event_links (user_id, source_type, source_id, google_event_id, last_hash, last_error, synced_at) VALUES (?, ?, ?, ?, ?, ?, NOW()) ON DUPLICATE KEY UPDATE google_event_id=VALUES(google_event_id), last_hash=VALUES(last_hash), last_error=NULL, synced_at=NOW()');
            $stmt->bind_param('isisss', $userId, $sourceType, $sourceId, $googleEventId, $hash, $emptyError);
            $stmt->execute();
        } catch (Throwable $exception) {
            $failed++;
            $exportFailed++;
            $message = mb_substr($exception->getMessage(), 0, 1000);
            $stmt = $db->prepare('INSERT INTO google_calendar_event_links (user_id, source_type, source_id, google_event_id, last_hash, last_error, synced_at) VALUES (?, ?, ?, ?, ?, ?, NOW()) ON DUPLICATE KEY UPDATE last_error=VALUES(last_error), synced_at=NOW()');
            $emptyId = '';
            $unsyncedHash = '';
            $stmt->bind_param('isisss', $userId, $sourceType, $sourceId, $emptyId, $unsyncedHash, $message);
            $stmt->execute();
        }
    }
    // Erst nach erfolgreicher Neuzuordnung werden alte JeMa-Projektionen ausgeblendet.
    if ($exportFailed === 0) {
        foreach (dbAll($db, "SELECT l.source_type, l.source_id, l.google_event_id FROM google_calendar_event_links l
            WHERE l.user_id=? AND l.google_event_id<>'' AND COALESCE(l.last_hash,'')<>'retired'
              AND l.source_type IN ('application','application_created','application_status','application_next_action','contact_log','calendar','workflow_event','application_day')", 'i', [$userId]) as $obsolete) {
            if (isset($activeExports[$obsolete['source_type'] . ':' . $obsolete['source_id']])) { continue; }
            try {
                $url = 'https://www.googleapis.com/calendar/v3/calendars/' . rawurlencode($calendarId) . '/events/' . rawurlencode($obsolete['google_event_id']);
                try {
                    $remote = googleJsonRequest('GET', $url, ['Authorization: Bearer ' . $token]);
                } catch (RuntimeException $exception) {
                    if (!in_array($exception->getCode(), [404, 410], true)) { throw $exception; }
                    $remote = ['status' => 'cancelled'];
                }
                if (($remote['status'] ?? '') !== 'cancelled') {
                    if (!googleCalendarOwnsEvent($remote, $obsolete['source_type'], (int)$obsolete['source_id']) || !empty($remote['attendees'])) {
                        throw new RuntimeException('Calendar repair requires manual review');
                    }
                    backupGoogleCalendarEvent($db, $userId, $calendarId, $remote);
                    $headers = ['Authorization: Bearer ' . $token];
                    if (!empty($remote['etag'])) { $headers[] = 'If-Match: ' . $remote['etag']; }
                    googleJsonRequest('PATCH', $url, $headers, ['status' => 'cancelled']);
                }
                cascadeExec($db, "UPDATE google_calendar_event_links SET last_hash='retired', last_error=NULL, synced_at=NOW() WHERE user_id=? AND source_type=? AND source_id=?", 'isi', [$userId, $obsolete['source_type'], (int)$obsolete['source_id']]);
            } catch (Throwable $exception) {
                $failed++;
                cascadeExec($db, 'UPDATE google_calendar_event_links SET last_error=? WHERE user_id=? AND source_type=? AND source_id=?', 'sisi', [mb_substr($exception->getMessage(), 0, 1000), $userId, $obsolete['source_type'], (int)$obsolete['source_id']]);
            }
        }
    }
    $lastError = $failed > 0 ? ($importError ?? (string)$failed . ' sync errors') : null;
    $stmt = $db->prepare('UPDATE user_google_calendar_settings SET last_sync_at=NOW(), last_error=? WHERE user_id=?');
    $stmt->bind_param('si', $lastError, $userId);
    $stmt->execute();
    return ['created' => $created, 'updated' => $updated, 'deleted' => (int) $importResult['deleted'], 'failed' => $failed];
}

function googleCalendarEventPayload(array $config, array $event, array $user): array
{
    $event['all_day'] = 0;
    $times = calendarRemoteTimes($event, $user);
    $description = trim((string) ($event['meta'] ?? '') . "\n" . (string) ($event['notes'] ?? ''));
    $href = (string) ($event['href'] ?? '');
    if ($href !== '' && $href !== '#') {
        $description = trim($description . "\n" . absoluteUrl($config, $href));
    }
    return [
        'summary' => implode(' · ', array_filter([(string)($event['company_name'] ?? ''), (string)$event['title']])),
        'description' => $description,
        'location' => (string)($event['location'] ?? ''),
        'start' => $times['start'],
        'end' => $times['end'],
        'transparency' => ($event['entry_kind'] ?? '') === 'milestone' ? 'transparent' : 'opaque',
        ...(($event['entry_kind'] ?? '') === 'milestone' ? ['reminders' => ['useDefault' => false, 'overrides' => []]] : []),
        'extendedProperties' => ['private' => [
            'jema_source' => (string) $event['source'],
            'jema_id' => (string) $event['id'],
        ]],
    ];
}

function googleCalendarSyncHash(array $event): string
{
    return hash('sha256', json_encode([
        'payload_version' => 5,
        'all_day' => (int)($event['all_day'] ?? 0),
        'location' => (string)($event['location'] ?? ''),
        'entry_kind' => (string)($event['entry_kind'] ?? ''),
        'company_name' => (string)($event['company_name'] ?? ''),
        'job_title' => (string)($event['job_title'] ?? ''),
        'title' => (string) ($event['title'] ?? ''),
        'meta' => (string) ($event['meta'] ?? ''),
        'notes' => (string) ($event['notes'] ?? ''),
        'starts_at' => (string) ($event['starts_at'] ?? ''),
        'ends_at' => (string) ($event['ends_at'] ?? ''),
        'href' => (string) ($event['href'] ?? ''),
    ], JSON_UNESCAPED_UNICODE));
}

function googleCalendarDateTime(array $value, DateTimeZone $timezone): array
{
    if (!empty($value['date'])) {
        $start = new DateTimeImmutable((string) $value['date'], $timezone);
        return [$start->format('Y-m-d H:i:s'), true];
    }
    $dateTime = trim((string) ($value['dateTime'] ?? ''));
    if ($dateTime === '') {
        throw new RuntimeException('Google event without start time');
    }
    return [(new DateTimeImmutable($dateTime))->setTimezone($timezone)->format('Y-m-d H:i:s'), false];
}

function importGoogleCalendarEvents(mysqli $db, string $token, string $calendarId, int $userId, array $user, DateTimeImmutable $start, DateTimeImmutable $end): array
{
    $timezone = new DateTimeZone((string) ($user['timezone'] ?? 'Europe/Zurich'));
    $url = 'https://www.googleapis.com/calendar/v3/calendars/' . rawurlencode($calendarId) . '/events?' . http_build_query([
        'singleEvents' => 'true',
        'showDeleted' => 'true',
        'maxResults' => 2500,
        'timeMin' => $start->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d\\TH:i:s\\Z'),
        'timeMax' => $end->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d\\TH:i:s\\Z'),
    ], '', '&', PHP_QUERY_RFC3986);
    $created = 0;
    $updated = 0;
    $deleted = 0;
    do {
        $response = googleJsonRequest('GET', $url, ['Authorization: Bearer ' . $token]);
        foreach ((array) ($response['items'] ?? []) as $googleEvent) {
            $googleEventId = trim((string) ($googleEvent['id'] ?? ''));
            if ($googleEventId === '') {
                continue;
            }
            $private = (array) ($googleEvent['extendedProperties']['private'] ?? []);
            if (trim((string) ($private['jema_source'] ?? '')) !== '') {
                continue;
            }
            $link = dbOne($db, 'SELECT calendar_event_id FROM google_calendar_import_links WHERE user_id=? AND google_event_id=? LIMIT 1', 'is', [$userId, $googleEventId]);
            if ((string) ($googleEvent['status'] ?? '') === 'cancelled') {
                if ($link) {
                    $stmt = $db->prepare('DELETE FROM calendar_events WHERE id=? AND owner_user_id=?');
                    $calendarEventId = (int) $link['calendar_event_id'];
                    $stmt->bind_param('ii', $calendarEventId, $userId);
                    $stmt->execute();
                    $deleted++;
                }
                continue;
            }
            try {
                [$startsAt, $allDay] = googleCalendarDateTime((array) ($googleEvent['start'] ?? []), $timezone);
                [$endsAt] = googleCalendarDateTime((array) ($googleEvent['end'] ?? []), $timezone);
            } catch (Throwable $ignored) {
                continue;
            }
            $title = trim((string) ($googleEvent['summary'] ?? '')) ?: tr('calendar.event');
            $notes = trim((string) ($googleEvent['description'] ?? '')) ?: null;
            $location = trim((string) ($googleEvent['location'] ?? '')) ?: null;
            $allDayValue = $allDay ? 1 : 0;
            $status = 'planned';
            if ($link) {
                $stmt = $db->prepare('UPDATE calendar_events SET title=?, event_type="other", starts_at=?, ends_at=?, all_day=?, status=?, location=?, notes=? WHERE id=? AND owner_user_id=?');
                $calendarEventId = (int) $link['calendar_event_id'];
                $stmt->bind_param('sssisssii', $title, $startsAt, $endsAt, $allDayValue, $status, $location, $notes, $calendarEventId, $userId);
                $stmt->execute();
                $updated++;
            } else {
                $stmt = $db->prepare('INSERT INTO calendar_events (owner_user_id, title, event_type, starts_at, ends_at, all_day, status, location, notes) VALUES (?, ?, "other", ?, ?, ?, ?, ?, ?)');
                $stmt->bind_param('isssisss', $userId, $title, $startsAt, $endsAt, $allDayValue, $status, $location, $notes);
                $stmt->execute();
                $calendarEventId = (int) $stmt->insert_id;
                $created++;
            }
            $googleUpdatedAt = !empty($googleEvent['updated']) ? (new DateTimeImmutable((string) $googleEvent['updated']))->format('Y-m-d H:i:s') : null;
            $googleEtag = trim((string) ($googleEvent['etag'] ?? '')) ?: null;
            $stmt = $db->prepare('INSERT INTO google_calendar_import_links (user_id, google_event_id, calendar_event_id, google_updated_at, google_etag, synced_at) VALUES (?, ?, ?, ?, ?, NOW()) ON DUPLICATE KEY UPDATE calendar_event_id=VALUES(calendar_event_id), google_updated_at=VALUES(google_updated_at), google_etag=VALUES(google_etag), synced_at=NOW()');
            $stmt->bind_param('isiss', $userId, $googleEventId, $calendarEventId, $googleUpdatedAt, $googleEtag);
            $stmt->execute();
        }
        $nextPageToken = trim((string) ($response['nextPageToken'] ?? ''));
        $url = $nextPageToken === '' ? '' : 'https://www.googleapis.com/calendar/v3/calendars/' . rawurlencode($calendarId) . '/events?' . http_build_query([
            'singleEvents' => 'true',
            'showDeleted' => 'true',
            'maxResults' => 2500,
            'timeMin' => $start->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d\\TH:i:s\\Z'),
            'timeMax' => $end->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d\\TH:i:s\\Z'),
            'pageToken' => $nextPageToken,
        ], '', '&', PHP_QUERY_RFC3986);
    } while ($url !== '');
    return ['created' => $created, 'updated' => $updated, 'deleted' => $deleted];
}

function syncGoogleCalendarEvents(mysqli $db, array $config, int $userId, array $user): array
{
    $lock = 'jema-calendar-' . $userId;
    if ((int)(dbOne($db, 'SELECT GET_LOCK(?, 0) acquired', 's', [$lock])['acquired'] ?? 0) !== 1) {
        throw new RuntimeException('Calendar synchronization already running');
    }
    try {
        return syncGoogleCalendarEventsLocked($db, $config, $userId, $user);
    } finally {
        dbOne($db, 'SELECT RELEASE_LOCK(?) released', 's', [$lock]);
    }
}

function calendarLocalEvent(mysqli $db, int $userId, int $eventId): ?array
{
    return dbOne($db, 'SELECT id, application_id, title, event_type, entry_kind, source_type, starts_at, ends_at, all_day, status, location, notes FROM calendar_events WHERE id=? AND owner_user_id=? LIMIT 1', 'ii', [$eventId, $userId]);
}

function googleImportedCalendarEventPayload(array $event, array $user): array
{
    $payload = [
        'summary' => (string) $event['title'],
        'description' => (string) ($event['notes'] ?? ''),
        'location' => (string) ($event['location'] ?? ''),
    ];
    return $payload + calendarRemoteTimes($event, $user);
}

function syncImportedCalendarEvent(mysqli $db, array $config, int $userId, array $user, array $event): void
{
    $link = dbOne($db, 'SELECT google_event_id FROM google_calendar_import_links WHERE user_id=? AND calendar_event_id=? LIMIT 1', 'ii', [$userId, (int) $event['id']]);
    if (!$link) {
        return;
    }
    $settings = googleCalendarSettings($db, $userId);
    if (!$settings || !(int) ($settings['sync_enabled'] ?? 0)) {
        return;
    }
    $token = googleAccessToken($db, $config, $userId, $settings);
    $calendarId = trim((string) ($settings['calendar_id'] ?? '')) ?: 'primary';
    googleJsonRequest('PATCH', 'https://www.googleapis.com/calendar/v3/calendars/' . rawurlencode($calendarId) . '/events/' . rawurlencode((string) $link['google_event_id']), ['Authorization: Bearer ' . $token], googleImportedCalendarEventPayload($event, $user));
}

function deleteGoogleCalendarEvent(mysqli $db, array $config, int $userId, array $user, int $eventId): void
{
    $link = dbOne($db, 'SELECT google_event_id FROM google_calendar_import_links WHERE user_id=? AND calendar_event_id=? LIMIT 1', 'ii', [$userId, $eventId]);
    if (!$link) {
        $link = dbOne($db, 'SELECT google_event_id FROM google_calendar_event_links WHERE user_id=? AND source_type="calendar" AND source_id=? LIMIT 1', 'ii', [$userId, $eventId]);
    }
    if (!$link || trim((string) ($link['google_event_id'] ?? '')) === '') {
        return;
    }
    $settings = googleCalendarSettings($db, $userId);
    if (!$settings || !(int) ($settings['sync_enabled'] ?? 0)) {
        return;
    }
    $token = googleAccessToken($db, $config, $userId, $settings);
    $calendarId = trim((string) ($settings['calendar_id'] ?? '')) ?: 'primary';
    googleJsonRequest('DELETE', 'https://www.googleapis.com/calendar/v3/calendars/' . rawurlencode($calendarId) . '/events/' . rawurlencode((string) $link['google_event_id']), ['Authorization: Bearer ' . $token]);
}

function syncCalendarAutomatically(mysqli $db, array $config, int $userId, array $user): void
{
    $settings = googleCalendarSettings($db, $userId);
    if (!$settings || !(int) ($settings['sync_enabled'] ?? 0) || empty($settings['refresh_token_encrypted'])) {
        return;
    }
    try {
        syncGoogleCalendarEvents($db, $config, $userId, $user);
    } catch (Throwable $exception) {
        error_log('Google calendar synchronization failed: ' . $exception->getMessage());
    }
}

function localeForCountry(?string $countryCode): string
{
    return match (strtoupper((string) $countryCode)) {
        'CH' => 'de_CH',
        'DE' => 'de_DE',
        'AT' => 'de_AT',
        'FR' => 'fr_FR',
        'IT' => 'it_IT',
        'ES' => 'es_ES',
        'PT' => 'pt_PT',
        'GB' => 'en_GB',
        default => 'de_CH',
    };
}

function displayDateTime(?string $value, ?array $user = null, bool $withTime = true): string
{
    if (!$value) {
        return '';
    }
    try {
        $timezone = new DateTimeZone((string) ($user['timezone'] ?? 'Europe/Zurich'));
        $date = new DateTimeImmutable($value, $timezone);
        $locale = localeForCountry($user['country_code'] ?? 'CH');
        if (class_exists(IntlDateFormatter::class)) {
            $formatter = new IntlDateFormatter(
                $locale,
                IntlDateFormatter::MEDIUM,
                $withTime ? IntlDateFormatter::SHORT : IntlDateFormatter::NONE,
                $timezone->getName()
            );
            $formatted = $formatter->format($date);
            if ($formatted !== false) {
                return $formatted;
            }
        }
        return $date->format($withTime ? 'd.m.Y H:i' : 'd.m.Y');
    } catch (Throwable) {
        return (string) $value;
    }
}

function percentageRangeLabel(mixed $min, mixed $max): string
{
    $minValue = trim((string)($min ?? ''));
    $maxValue = trim((string)($max ?? ''));
    if ($minValue === '' && $maxValue === '') {
        return '';
    }
    $format = static function (string $value): string {
        if ($value === '') {
            return '';
        }
        $number = (float)$value;
        $formatted = abs($number - round($number)) < 0.0001 ? (string)(int)round($number) : rtrim(rtrim(number_format($number, 2, '.', ''), '0'), '.');
        return $formatted . '%';
    };
    if ($minValue !== '' && $maxValue !== '' && (float)$minValue === (float)$maxValue) {
        return $format($minValue);
    }
    if ($minValue !== '' && $maxValue !== '') {
        return $format($minValue) . ' - ' . $format($maxValue);
    }
    return $format($minValue !== '' ? $minValue : $maxValue);
}

function storageRoot(): string
{
    return __DIR__ . '/storage/documents';
}

function ensureDocumentStorage(int $userId): string
{
    $root = storageRoot();
    if (!is_dir($root)) {
        mkdir($root, 0775, true);
    }
    $deny = dirname($root) . '/.htaccess';
    if (!is_file($deny)) {
        file_put_contents($deny, "Require all denied\n");
    }
    $dir = $root . '/' . $userId;
    if (!is_dir($dir)) {
        mkdir($dir, 0775, true);
    }
    return $dir;
}

function uploadDocumentFile(array $file, int $userId): array
{
    if (($file['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_OK) {
        throw new RuntimeException(tr('documents.error_upload_failed'));
    }
    if ((int) $file['size'] > 25 * 1024 * 1024) {
        throw new RuntimeException(tr('documents.error_too_large'));
    }
    $original = basename((string) $file['name']);
    $extension = strtolower(pathinfo($original, PATHINFO_EXTENSION));
    $allowed = ['pdf','doc','docx','jpg','jpeg','png','txt'];
    if (!in_array($extension, $allowed, true)) {
        throw new RuntimeException(tr('documents.error_type_not_allowed'));
    }
    $dir = ensureDocumentStorage($userId);
    $name = bin2hex(random_bytes(18)) . '.' . $extension;
    $target = $dir . '/' . $name;
    if (!move_uploaded_file((string) $file['tmp_name'], $target)) {
        throw new RuntimeException(tr('documents.error_save_failed'));
    }
    $mime = function_exists('mime_content_type') ? (mime_content_type($target) ?: 'application/octet-stream') : 'application/octet-stream';
    return [
        'original' => $original,
        'path' => 'storage/documents/' . $userId . '/' . $name,
        'mime' => $mime,
        'size' => filesize($target) ?: (int) $file['size'],
        'sha256' => hash_file('sha256', $target),
    ];
}

function dbOne(mysqli $db, string $sql, string $types = '', array $values = []): ?array
{
    if (!method_exists(mysqli_stmt::class, 'get_result')) {
        $rows = queryRowsWithoutMysqlnd($db, $sql, $types, $values, 1);
        return $rows[0] ?? null;
    }
    $stmt = $db->prepare($sql);
    if ($types !== '') {
        $stmt->bind_param($types, ...$values);
    }
    $stmt->execute();
    $rows = statementRows($stmt, 1);
    return $rows[0] ?? null;
}

function dbAll(mysqli $db, string $sql, string $types = '', array $values = []): array
{
    if (!method_exists(mysqli_stmt::class, 'get_result')) {
        return queryRowsWithoutMysqlnd($db, $sql, $types, $values);
    }
    $stmt = $db->prepare($sql);
    if ($types !== '') {
        $stmt->bind_param($types, ...$values);
    }
    $stmt->execute();
    return statementRows($stmt);
}

function statementRows(mysqli_stmt $stmt, ?int $limit = null): array
{
    $result = $stmt->get_result();
    if (!$result) {
        return [];
    }

    $rows = [];
    while ($row = $result->fetch_assoc()) {
        $rows[] = $row;
        if ($limit !== null && count($rows) >= $limit) {
            break;
        }
    }
    return $rows;
}

function queryRowsWithoutMysqlnd(mysqli $db, string $sql, string $types = '', array $values = [], ?int $limit = null): array
{
    $query = interpolateSql($db, $sql, $types, $values);
    $result = $db->query($query);
    if (!($result instanceof mysqli_result)) {
        return [];
    }
    $rows = [];
    while ($row = $result->fetch_assoc()) {
        $rows[] = $row;
        if ($limit !== null && count($rows) >= $limit) {
            break;
        }
    }
    $result->free();
    return $rows;
}

function interpolateSql(mysqli $db, string $sql, string $types, array $values): string
{
    if ($types === '') {
        return $sql;
    }
    $offset = 0;
    foreach ($values as $index => $value) {
        $pos = strpos($sql, '?', $offset);
        if ($pos === false) {
            break;
        }
        $type = $types[$index] ?? 's';
        if ($value === null) {
            $replacement = 'NULL';
        } elseif ($type === 'i') {
            $replacement = (string) (int) $value;
        } elseif ($type === 'd') {
            $replacement = (string) (float) $value;
        } else {
            $replacement = "'" . $db->real_escape_string((string) $value) . "'";
        }
        $sql = substr($sql, 0, $pos) . $replacement . substr($sql, $pos + 1);
        $offset = $pos + strlen($replacement);
    }
    return $sql;
}

function applicationDocumentAttachmentState(mysqli $db, int $userId, int $applicationId): array
{
    $rows = dbAll(
        $db,
        'SELECT ad.user_document_id, d.id, d.original_filename, d.storage_path, d.mime_type, d.file_size, d.deleted_at
           FROM application_documents ad
           LEFT JOIN user_documents d ON d.id=ad.user_document_id AND d.user_id=?
          WHERE ad.application_id=?
          ORDER BY ad.sort_order, d.scope DESC, d.title, d.version DESC',
        'ii',
        [$userId, $applicationId]
    );
    $root = realpath(storageRoot());
    $files = [];
    $missing = [];
    foreach ($rows as $row) {
        $filename = trim((string) ($row['original_filename'] ?? ''));
        $missingLabel = $filename !== '' ? $filename : tr('applications.unnamed_document');
        if (empty($row['id']) || !empty($row['deleted_at'])) {
            $missing[] = $missingLabel;
            continue;
        }
        $path = realpath(__DIR__ . '/' . (string) $row['storage_path']);
        if (!$root || !$path || !str_starts_with($path, $root) || !is_file($path) || !is_readable($path)) {
            $missing[] = $missingLabel;
            continue;
        }
        $files[] = [
            'id' => (int) $row['id'],
            'filename' => (string) $row['original_filename'],
            'path' => $path,
            'mime' => (string) ($row['mime_type'] ?: 'application/octet-stream'),
            'size' => (int) $row['file_size'],
        ];
    }
    return ['files' => $files, 'missing' => array_values(array_unique($missing))];
}

function applicationDocumentFiles(mysqli $db, int $userId, int $applicationId): array
{
    return applicationDocumentAttachmentState($db, $userId, $applicationId)['files'];
}

function zipSafeName(string $filename, array &$used): string
{
    $name = preg_replace('/[\\\\\/:*?"<>|]+/', '_', basename($filename)) ?: 'dokument.pdf';
    $base = pathinfo($name, PATHINFO_FILENAME);
    $extension = pathinfo($name, PATHINFO_EXTENSION);
    $candidate = $name;
    $i = 2;
    while (isset($used[mb_strtolower($candidate)])) {
        $candidate = $base . '-' . $i . ($extension !== '' ? '.' . $extension : '');
        $i++;
    }
    $used[mb_strtolower($candidate)] = true;
    return $candidate;
}

function applicationTempRoot(): string
{
    return __DIR__ . '/storage/temp/application-documents';
}

function removeTree(string $path): void
{
    if (!is_dir($path)) {
        return;
    }
    foreach (scandir($path) ?: [] as $entry) {
        if ($entry === '.' || $entry === '..') {
            continue;
        }
        $target = $path . '/' . $entry;
        is_dir($target) ? removeTree($target) : @unlink($target);
    }
    @rmdir($path);
}

function cleanupApplicationTempPackages(): void
{
    $packages = $_SESSION['application_temp_packages'] ?? [];
    $root = applicationTempRoot();
    foreach ($packages as $token => $package) {
        if ((int) ($package['expires_at'] ?? 0) >= time()) {
            continue;
        }
        removeTree((string) ($package['dir'] ?? ''));
        unset($packages[$token]);
    }
    $_SESSION['application_temp_packages'] = $packages;
    if (is_dir($root)) {
        foreach (scandir($root) ?: [] as $entry) {
            if ($entry === '.' || $entry === '..') {
                continue;
            }
            $target = $root . '/' . $entry;
            if (is_dir($target) && filemtime($target) !== false && filemtime($target) < time() - 7200) {
                removeTree($target);
            }
        }
    }
}

function createApplicationTempPackage(mysqli $db, int $userId, int $applicationId): ?array
{
    cleanupApplicationTempPackages();
    $files = applicationDocumentFiles($db, $userId, $applicationId);
    if (!$files) {
        return null;
    }
    $root = applicationTempRoot();
    if (!is_dir($root)) {
        mkdir($root, 0775, true);
    }
    $token = bin2hex(random_bytes(16));
    $dir = $root . '/' . $userId . '-' . $applicationId . '-' . $token;
    mkdir($dir, 0775, true);
    $used = [];
    $items = [];
    foreach ($files as $file) {
        $name = zipSafeName((string) $file['filename'], $used);
        $target = $dir . '/' . $name;
        if (!copy((string) $file['path'], $target)) {
            continue;
        }
        $items[] = [
            'name' => $name,
            'size' => (int) filesize($target),
            'mime' => (string) $file['mime'],
        ];
    }
    if (!$items) {
        removeTree($dir);
        return null;
    }
    $package = [
        'application_id' => $applicationId,
        'dir' => $dir,
        'expires_at' => time() + 3600,
        'items' => $items,
    ];
    $_SESSION['application_temp_packages'][$token] = $package;
    return ['token' => $token] + $package;
}

function isAdmin(mysqli $db, int $userId, array $config = []): bool
{
    if ($userId < 1) {
        return false;
    }
    $user = dbOne($db, 'SELECT email FROM users WHERE id=? AND deleted_at IS NULL', 'i', [$userId]);
    $adminEmails = array_map('strtolower', (array) ($config['admin_emails'] ?? ['admin@jema.business']));
    if ($user && in_array(strtolower((string) $user['email']), $adminEmails, true)) {
        return true;
    }
    $role = dbOne(
        $db,
        "SELECT 1 is_admin FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=? AND r.code='admin' LIMIT 1",
        'i',
        [$userId]
    );
    return (bool) $role;
}

function activeSupportGrant(mysqli $db, int $userId): ?array
{
    if ($userId < 1) {
        return null;
    }
    try {
        return dbOne($db, 'SELECT * FROM support_access_grants WHERE user_id=? AND revoked_at IS NULL ORDER BY granted_at DESC LIMIT 1', 'i', [$userId]);
    } catch (Throwable) {
        return null;
    }
}

function userLabel(array $user): string
{
    $name = trim((string) ($user['first_name'] ?? '') . ' ' . (string) ($user['last_name'] ?? ''));
    return $name !== '' ? $name : (string) ($user['email'] ?? 'Benutzer');
}

function audit(mysqli $db, int $userId, string $action, string $entityType, int $entityId, ?array $old, ?array $new): void
{
    $stmt = $db->prepare(
        'INSERT INTO audit_log (user_id, action, entity_type, entity_id, old_values, new_values, ip_address, user_agent) '
        . 'VALUES (?, ?, ?, ?, ?, ?, INET6_ATON(?), ?)'
    );
    $oldJson = $old === null ? null : json_encode($old, JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR);
    $newJson = $new === null ? null : json_encode($new, JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR);
    $ip = (string) ($_SERVER['REMOTE_ADDR'] ?? '');
    $agent = substr((string) ($_SERVER['HTTP_USER_AGENT'] ?? ''), 0, 500);
    $stmt->bind_param('ississss', $userId, $action, $entityType, $entityId, $oldJson, $newJson, $ip, $agent);
    $stmt->execute();
}

