                <label><?= e(tr('applications.application')) ?><select name="mail_application_id"><option value="0"><?= e(tr('common.not_selected')) ?></option><?php foreach($applications as $application): ?><option value="<?= (int)$application['id'] ?>" data-company-id="<?= (int)$application['company_id'] ?>" data-contact-id="<?= (int)($application['primary_contact_id'] ?? 0) ?>" <?= (int)$application['id']===$selectedApplicationId?'selected':'' ?>><?= e($application['title'].' · '.$application['company_name']) ?></option><?php endforeach; ?></select></label>
            </div>
            <div class="three">
                <label><?= e(tr('applications.channel')) ?><select name="mail_channel"><?php foreach($channels as $value=>$label): ?><option value="<?= e($value) ?>"><?= e($label) ?></option><?php endforeach; ?></select></label>
                <label><?= e(tr('contact_log.direction')) ?><select name="mail_direction"><option value="incoming"><?= e(tr('contact_log.direction.incoming')) ?></option><option value="outgoing"><?= e(tr('contact_log.direction.outgoing')) ?></option><option value="internal"><?= e(tr('contact_log.direction.internal')) ?></option></select></label>
                <label><?= e(tr('mail_activity.application_status')) ?><select name="mail_application_status"><option value=""><?= e(tr('mail_activity.status_no_change')) ?></option><?php foreach(applicationStatusOptions(false) as $value=>$label): ?><option value="<?= e($value) ?>"><?= e($label) ?></option><?php endforeach; ?></select></label>
            </div>
            <label><?= e(tr('contact_log.occurred_at')) ?><input type="datetime-local" name="mail_occurred_at" value="<?= e($occurred) ?>" required></label>
            <label><?= e(tr('contact_log.subject')) ?><input name="mail_subject" required></label>
            <label><?= e(tr('mail_activity.mail_text')) ?><textarea name="mail_body" rows="7" required></textarea></label>
            <?= filePickerHtml('log_attachment', false) ?>
            <div class="actions"><button class="primary" name="action" value="save_mail_activity"><?= e(tr('mail_activity.save')) ?></button></div>
        </form>
    </section>
    <script>
    (() => {
        const root = document.getElementById('mail-activity');
        if (!root) return;
        const company = root.querySelector('[name="mail_company_id"]');
        const contact = root.querySelector('[name="mail_contact_id"]');
        const application = root.querySelector('[name="mail_application_id"]');
        application?.addEventListener('change', () => {
            const selected = application.options[application.selectedIndex];
            if (selected?.dataset.companyId && company) company.value = selected.dataset.companyId;
            if (selected?.dataset.contactId && selected.dataset.contactId !== '0' && contact) contact.value = selected.dataset.contactId;
        });
        contact?.addEventListener('change', () => {
            const selected = contact.options[contact.selectedIndex];
            if (selected?.dataset.companyId && company) company.value = selected.dataset.companyId;
        });
    })();
    </script>
    <?php
    return (string) ob_get_clean();
}

try { seedReviewedHelp($db); } catch (Throwable $error) { error_log('Help content update failed: '.$error->getMessage()); }
$page = (string) ($_GET['page'] ?? (userId() ? 'dashboard' : 'login'));
if ($page === 'pendents') { redirect('/?page=calendar&view=agenda'); }
$action = (string) ($_POST['action'] ?? '');
$currentUser = userId() ? dbOne($db, 'SELECT * FROM users WHERE id=? AND deleted_at IS NULL', 'i', [userId()]) : null;
if ($currentUser) {
    $requestTimezone = (string)($currentUser['timezone'] ?? 'Europe/Zurich');
    if (!in_array($requestTimezone, DateTimeZone::listIdentifiers(), true)) { $requestTimezone = 'Europe/Zurich'; }
    date_default_timezone_set($requestTimezone);
    $db->query("SET time_zone='" . (new DateTimeImmutable('now'))->format('P') . "'");
}
if (isset($_GET['lang'])) {
    $_SESSION['locale'] = normalizeLocale((string) $_GET['lang']);
}
csrfToken();

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verifyCsrf();

    if ($action === 'apply_workflow_migration') {
        requireLogin();
        if (userId() !== realUserId() || !isAdmin($db, userId(), $config)) { http_response_code(403); exit('Forbidden'); }
        try {
            migrateWorkflowCalendarV6($db, (string)($_POST['preview_hash'] ?? ''));
            audit($db, userId(), 'other', 'workflow', 6, null, ['migration'=>'workflow_calendar_v6']);
            flash(tr('common.saved'));
        } catch (Throwable $exception) {
            error_log('Workflow migration failed: ' . $exception->getMessage());
            flash(tr('workflow.changed'), 'danger');
        }
        redirect('/?page=workflow_review');
    }

    if ($action === 'test_openai_connection') {
        requireLogin();
        if (userId() !== realUserId() || !isAdmin($db, userId(), $config)) { http_response_code(403); exit('Forbidden'); }
        try {
            $result = openAiConnectionCheck($config, userId());
            audit($db, userId(), 'other', 'openai_connection', 0, null, ['model'=>$result['model'],'response_id'=>$result['response_id']]);
            flash('OpenAI-Verbindung erfolgreich: ' . $result['model']);
        } catch (Throwable $exception) {
            error_log('OpenAI connection test failed: ' . $exception->getMessage());
            flash('OpenAI-Verbindung fehlgeschlagen. Prüfe die geschützte Serverkonfiguration und das Fehlerprotokoll.', 'danger');
        }
        redirect('/?page=admin_ai');
    }

    if ($action === 'register') {
        $email = strtolower(trim((string) $_POST['email']));
        $first = trim((string) $_POST['first_name']);
        $last = trim((string) $_POST['last_name']);
        $password = (string) $_POST['password'];
        $preferredLanguage = normalizeLocale((string) ($_POST['preferred_language'] ?? currentLocale(null)));
        if (!filter_var($email, FILTER_VALIDATE_EMAIL) || strlen($password) < 10 || $first === '' || $last === '') {
            flash(tr('flash.auth.register_invalid'), 'danger');
            redirect('/?page=register');
        }
        try {
            $emailNeedsVerification = outboundEmailEnabled($config);
            $stmt = $db->prepare(
                "INSERT INTO users (email, password_hash, status, preferred_language, first_name, last_name, email_verified_at) "
                . "VALUES (?, ?, 'active', ?, ?, ?, " . ($emailNeedsVerification ? 'NULL' : 'NOW()') . ")"
            );
            $hash = password_hash($password, PASSWORD_DEFAULT);
            $stmt->bind_param('sssss', $email, $hash, $preferredLanguage, $first, $last);
            $stmt->execute();
            $newUserId = (int) $stmt->insert_id;
            audit($db, $newUserId, 'create', 'user', $newUserId, null, ['email' => $email]);
            unset($_SESSION['email_verify_link'], $_SESSION['email_verify_notice']);
            if ($emailNeedsVerification) {
                $token = bin2hex(random_bytes(32));
                $expiresAt = (new DateTimeImmutable('+24 hours'))->format('Y-m-d H:i:s');
                $tokenType = 'email_verify';
                $tokenHash = hash('sha256', $token);
                $tokenStmt = $db->prepare('INSERT INTO auth_tokens (user_id, token_type, token_hash, expires_at) VALUES (?, ?, ?, ?)');
                $tokenStmt->bind_param('isss', $newUserId, $tokenType, $tokenHash, $expiresAt);
                $tokenStmt->execute();
                $verifyLink = absoluteUrl($config, '/?page=verify_email&token=' . urlencode($token));
                $subject = 'E-Mail fur JeMa Jobs bestaetigen';
                $body = "Hallo {$first}\n\nbitte bestaetige deine E-Mail-Adresse fur JeMa Jobs innerhalb von 24 Stunden:\n" . $verifyLink . "\n\nWenn du dich nicht registriert hast, kannst du diese Nachricht ignorieren.\n";
                try {
                    sendSmtpMail($config, $email, $subject, $body);
                    logOutboundEmail($db, $newUserId, $email, $subject, $body, 'sent');
                    $_SESSION['email_verify_notice'] = tr('flash.auth.registered_verify_mail');
                } catch (Throwable $exception) {
                    logOutboundEmail($db, $newUserId, $email, $subject, $body, 'failed', $exception->getMessage());
                    $_SESSION['email_verify_notice'] = tr('flash.auth.registered_verify_mail_failed');
                }
            } else {
                $_SESSION['email_verify_notice'] = tr('flash.auth.registered_mail_disabled');
            }
            flash(tr($emailNeedsVerification ? 'flash.auth.registered_verify' : 'flash.auth.registered_login'));
            redirect('/?page=login');
        } catch (mysqli_sql_exception $exception) {
            flash(tr('flash.auth.email_registered'), 'danger');
            redirect('/?page=register');
        }
    }

    if ($action === 'login') {
        $email = strtolower(trim((string) $_POST['email']));
        $password = (string) $_POST['password'];
        $user = dbOne($db, 'SELECT * FROM users WHERE email = ? AND deleted_at IS NULL', 's', [$email]);
        if (!$user || !password_verify($password, $user['password_hash'])) {
            flash(tr('flash.auth.login_failed'), 'danger');
            redirect('/?page=login');
        }
        if (in_array((string) $user['status'], ['locked', 'disabled'], true)) {
            flash(tr('flash.auth.account_inactive'), 'warning');
            redirect('/?page=login');
        }
        if (empty($user['email_verified_at'])) {
            flash(tr('flash.auth.email_unverified'), 'warning');
            redirect('/?page=login');
        }
        $loginLocale = !empty($_SESSION['locale'])
            ? normalizeLocale((string) $_SESSION['locale'])
            : normalizeLocale((string) ($user['preferred_language'] ?? 'de-CH'));
        if ($loginLocale !== normalizeLocale((string) ($user['preferred_language'] ?? 'de-CH'))) {
            $localeStmt = $db->prepare('UPDATE users SET preferred_language=? WHERE id=?');
            $userIdForLocale = (int) $user['id'];
            $localeStmt->bind_param('si', $loginLocale, $userIdForLocale);
            $localeStmt->execute();
            $user['preferred_language'] = $loginLocale;
        }
        $_SESSION['locale'] = $loginLocale;
        $totp = activeTotpMethod($db, (int) $user['id']);
        if ($totp) {
            session_regenerate_id(true);
            clearAuthenticatedSession();
            $_SESSION['pending_2fa_user_id'] = (int) $user['id'];
            $_SESSION['pending_2fa_user_name'] = $user['first_name'] . ' ' . $user['last_name'];
            redirect('/?page=two_factor');
        }
        session_regenerate_id(true);
        $_SESSION['user_id'] = (int) $user['id'];
        $_SESSION['user_name'] = $user['first_name'] . ' ' . $user['last_name'];
        $db->query('UPDATE users SET last_login_at = NOW(), last_seen_at = NOW() WHERE id = ' . (int) $user['id']);
        touchUserPresence($db, (int) $user['id']);
        audit($db, (int) $user['id'], 'login', 'user', (int) $user['id'], null, null);
        redirect('/');
    }

    if ($action === 'verify_two_factor') {
        $pendingUserId = (int) ($_SESSION['pending_2fa_user_id'] ?? 0);
        $user = $pendingUserId ? dbOne($db, 'SELECT * FROM users WHERE id=? AND deleted_at IS NULL', 'i', [$pendingUserId]) : null;
        $totp = $user ? activeTotpMethod($db, $pendingUserId) : null;
        if (!$user || !$totp || !verifyTotpCode((string) $totp['secret_encrypted'], (string) ($_POST['totp_code'] ?? ''))) {
            clearAuthenticatedSession();
            flash(tr('auth.totp_invalid'), 'danger');
            redirect('/?page=two_factor');
        }
        unset($_SESSION['pending_2fa_user_id'], $_SESSION['pending_2fa_user_name']);
        session_regenerate_id(true);
        $_SESSION['user_id'] = $pendingUserId;
        $_SESSION['user_name'] = $user['first_name'] . ' ' . $user['last_name'];
        $loginLocale = !empty($_SESSION['locale'])
            ? normalizeLocale((string) $_SESSION['locale'])
            : normalizeLocale((string) ($user['preferred_language'] ?? 'de-CH'));
        if ($loginLocale !== normalizeLocale((string) ($user['preferred_language'] ?? 'de-CH'))) {
            $localeStmt = $db->prepare('UPDATE users SET preferred_language=? WHERE id=?');
            $localeStmt->bind_param('si', $loginLocale, $pendingUserId);
            $localeStmt->execute();
            $user['preferred_language'] = $loginLocale;
        }
        $_SESSION['locale'] = $loginLocale;
        $db->query('UPDATE users SET last_login_at = NOW(), last_seen_at = NOW() WHERE id = ' . $pendingUserId);
        touchUserPresence($db, $pendingUserId);
        $stmt = $db->prepare('UPDATE two_factor_methods SET last_used_at=NOW() WHERE id=?');
        $methodId = (int) $totp['id'];
        $stmt->bind_param('i', $methodId);
        $stmt->execute();
        audit($db, $pendingUserId, 'login', 'user', $pendingUserId, null, ['two_factor' => 'totp']);
        redirect('/');
    }

    if ($action === 'request_password_reset') {
        $email = strtolower(trim((string) $_POST['email']));
        $user = filter_var($email, FILTER_VALIDATE_EMAIL)
            ? dbOne($db, "SELECT id, status FROM users WHERE email=? AND deleted_at IS NULL AND status NOT IN ('locked','disabled')", 's', [$email])
            : null;
        unset($_SESSION['password_reset_link']);
        unset($_SESSION['password_reset_notice']);
        if ($user) {
            $token = bin2hex(random_bytes(32));
            $tokenHash = hash('sha256', $token);
            $tokenType = 'password_reset';
            $stmt = $db->prepare('UPDATE auth_tokens SET consumed_at=NOW() WHERE user_id=? AND token_type=? AND consumed_at IS NULL');
            $stmt->bind_param('is', $user['id'], $tokenType);
            $stmt->execute();
            $expiresAt = (new DateTimeImmutable('+1 hour'))->format('Y-m-d H:i:s');
            $stmt = $db->prepare('INSERT INTO auth_tokens (user_id, token_type, token_hash, expires_at) VALUES (?, ?, ?, ?)');
            $stmt->bind_param('isss', $user['id'], $tokenType, $tokenHash, $expiresAt);
            $stmt->execute();
            $resetPath = '/?page=reset_password&token=' . urlencode($token);
            $resetLink = (appUrl($config) ?: '') . $resetPath;
            $subject = 'Passwort fur JeMa Jobs zurucksetzen';
            $body = "Hallo\n\nfur dein JeMa Jobs Konto wurde ein Passwort-Reset angefordert.\n\nBitte offne diesen Link innerhalb von 60 Minuten:\n" . $resetLink . "\n\nWenn du den Reset nicht angefordert hast, kannst du diese Nachricht ignorieren.\n";
            if (mailEnabledForUser($db, $config, (int) $user['id'])) {
                try {
                    sendConfiguredMail($db, $config, (int) $user['id'], $email, $subject, $body);
                    $_SESSION['password_reset_notice'] = tr('flash.auth.reset_mail_sent');
                } catch (Throwable $exception) {
                    $_SESSION['password_reset_notice'] = tr('flash.auth.reset_mail_failed');
                }
            } else {
                $_SESSION['password_reset_link'] = $resetLink;
                $_SESSION['password_reset_notice'] = tr('flash.auth.reset_link_created');
            }
            audit($db, (int) $user['id'], 'other', 'auth_token', (int) $stmt->insert_id, null, ['token_type' => 'password_reset']);
        } else {
            $_SESSION['password_reset_notice'] = tr('flash.auth.reset_no_account');
        }
        flash(tr('flash.auth.reset_prepared'), 'success');
        redirect('/?page=forgot_password&sent=1');
    }

    if ($action === 'reset_password') {
        $token = trim((string) ($_POST['token'] ?? ''));
        $password = (string) ($_POST['password'] ?? '');
        $confirm = (string) ($_POST['password_confirm'] ?? '');
        if ($token === '' || strlen($password) < 10 || $password !== $confirm) {
            flash(tr('flash.auth.reset_invalid'), 'danger');
            redirect('/?page=reset_password&token=' . urlencode($token));
        }
        $tokenHash = hash('sha256', $token);
        $reset = dbOne(
            $db,
            "SELECT t.id token_id, t.user_id, u.status
               FROM auth_tokens t
               JOIN users u ON u.id=t.user_id
              WHERE t.token_type='password_reset'
                AND t.token_hash=?
                AND t.consumed_at IS NULL
                AND t.expires_at > NOW()
                AND u.deleted_at IS NULL
              LIMIT 1",
            's',
            [$tokenHash]
        );
        if (!$reset || in_array((string) $reset['status'], ['locked', 'disabled'], true)) {
            flash(tr('flash.auth.reset_link_invalid'), 'danger');
            redirect('/?page=forgot_password');
        }
        $hash = password_hash($password, PASSWORD_DEFAULT);
        $stmt = $db->prepare('UPDATE users SET password_hash=?, failed_login_count=0, locked_until=NULL WHERE id=?');
        $stmt->bind_param('si', $hash, $reset['user_id']);
        $stmt->execute();
        $stmt = $db->prepare('UPDATE auth_tokens SET consumed_at=NOW() WHERE id=?');
        $stmt->bind_param('i', $reset['token_id']);
        $stmt->execute();
        audit($db, (int) $reset['user_id'], 'update', 'user', (int) $reset['user_id'], null, ['password_reset' => true]);
        unset($_SESSION['password_reset_link']);
        flash(tr('flash.auth.password_changed_login'));
        redirect('/?page=login');
    }

    if ($action === 'logout') {
        endUserPresenceSession($db, realUserId());
        session_destroy();
        redirect('/?page=login');
    }

    requireLogin();

    if ($action === 'stop_admin_support') {
        if (!isSupportImpersonation()) {
            redirect('/');
        }
        $targetId = userId();
        $adminId = realUserId();
        audit($db, $targetId, 'other', 'support_access', $targetId, null, ['admin_user_id' => $adminId, 'ended' => true]);
        endSupportImpersonationSession();
        flash(tr('flash.support.ended'));
        redirect('/?page=admin_users');
    }

    if ($action === 'grant_admin_support') {
        if (isSupportImpersonation()) {
            flash(tr('flash.support.grant_locked'), 'warning');
            redirect('/?page=profile#support-access');
        }
        $uid = userId();
        $stmt = $db->prepare('UPDATE support_access_grants SET revoked_at=NOW(), revoked_by_user_id=? WHERE user_id=? AND revoked_at IS NULL');
        $stmt->bind_param('ii', $uid, $uid);
        $stmt->execute();
        $stmt = $db->prepare('INSERT INTO support_access_grants (user_id, granted_by_user_id) VALUES (?, ?)');
        $stmt->bind_param('ii', $uid, $uid);
        $stmt->execute();
        audit($db, $uid, 'create', 'support_access', (int) $stmt->insert_id, null, ['granted' => true]);
        flash(tr('flash.support.granted'));
        redirect('/?page=profile#support-access');
    }

    if ($action === 'revoke_admin_support') {
        if (isSupportImpersonation()) {
            flash(tr('flash.support.grant_locked'), 'warning');
            redirect('/?page=profile#support-access');
        }
        $uid = userId();
        $stmt = $db->prepare('UPDATE support_access_grants SET revoked_at=NOW(), revoked_by_user_id=? WHERE user_id=? AND revoked_at IS NULL');
        $stmt->bind_param('ii', $uid, $uid);
        $stmt->execute();
        audit($db, $uid, 'delete', 'support_access', $uid, null, ['revoked' => true]);
        flash(tr('flash.support.revoked'));
        redirect('/?page=profile#support-access');
    }

    if ($action === 'admin_start_support') {
        $adminId = realUserId();
        if (!isAdmin($db, $adminId, $config)) {
            http_response_code(403);
            exit('Forbidden');
        }
        if (isSupportImpersonation()) {
            flash(tr('flash.support.end_current_first'), 'warning');
            redirect('/');
        }
        $targetUserId = (int) ($_POST['user_id'] ?? 0);
        if ($targetUserId === $adminId) {
            flash(tr('flash.support.own_account_blocked'), 'warning');
            redirect('/?page=admin_users');
        }
        $target = dbOne($db, "SELECT id, email, first_name, last_name, status FROM users WHERE id=? AND deleted_at IS NULL AND status NOT IN ('locked','disabled')", 'i', [$targetUserId]);
        $grant = activeSupportGrant($db, $targetUserId);
        if (!$target || !$grant) {
            flash(tr('flash.support.no_active_grant'), 'danger');
            redirect('/?page=admin_users');
        }
        $admin = dbOne($db, 'SELECT first_name, last_name, email FROM users WHERE id=? AND deleted_at IS NULL', 'i', [$adminId]) ?: [];
        session_regenerate_id(true);
        $_SESSION['support_admin_user_id'] = $adminId;
        $_SESSION['support_admin_name'] = userLabel($admin);
        $_SESSION['support_target_user_id'] = $targetUserId;
        $_SESSION['support_target_name'] = userLabel($target);
        $_SESSION['user_id'] = $targetUserId;
        $_SESSION['user_name'] = userLabel($target);
        audit($db, $targetUserId, 'other', 'support_access', (int) $grant['id'], null, ['admin_user_id' => $adminId, 'started' => true]);
        flash(strtr(tr('flash.support.started'), ['{user}' => userLabel($target)]));
        redirect('/');
    }

    if ($action === 'admin_create_user') {
        if (!isAdmin($db, realUserId(), $config)) {
            http_response_code(403);
            exit('Forbidden');
        }
        $email = strtolower(trim((string) ($_POST['email'] ?? '')));
        $firstName = trim((string) ($_POST['first_name'] ?? ''));
        $lastName = trim((string) ($_POST['last_name'] ?? ''));
        $password = (string) ($_POST['password'] ?? '');
        $status = in_array($_POST['status'] ?? '', ['invited', 'active'], true) ? (string) $_POST['status'] : 'invited';
        if (!filter_var($email, FILTER_VALIDATE_EMAIL) || $firstName === '' || $lastName === '' || strlen($password) < 10) {
            flash('Bitte Vorname, Nachname, gültige E-Mail-Adresse und ein Passwort mit mindestens 10 Zeichen angeben.', 'danger');
            redirect('/?page=admin_users&new_user=1');
        }
        try {
            $stmt = $db->prepare("INSERT INTO users (email, password_hash, status, preferred_language, first_name, last_name, email_verified_at) VALUES (?, ?, ?, 'de-CH', ?, ?, CASE WHEN ?='active' THEN NOW() ELSE NULL END)");
            $hash = password_hash($password, PASSWORD_DEFAULT);
            $stmt->bind_param('ssssss', $email, $hash, $status, $firstName, $lastName, $status);
            $stmt->execute();
            $newUserId = (int) $stmt->insert_id;
            audit($db, realUserId(), 'create', 'user', $newUserId, null, ['email' => $email, 'status' => $status]);
            flash('Benutzer wurde eröffnet.');
            redirect('/?page=admin_users');
        } catch (mysqli_sql_exception) {
            flash('Diese E-Mail-Adresse ist bereits registriert.', 'danger');
            redirect('/?page=admin_users&new_user=1');
        }
    }

    if ($action === 'admin_update_user') {
        if (!isAdmin($db, realUserId(), $config)) {
            http_response_code(403);
            exit('Forbidden');
        }
        $targetUserId = (int) ($_POST['user_id'] ?? 0);
        if ($targetUserId === realUserId()) {
            flash(tr('flash.admin.own_account_update_blocked'), 'warning');
            redirect('/?page=admin_users');
        }
        $target = dbOne($db, 'SELECT id, email, first_name, last_name, status FROM users WHERE id=? AND deleted_at IS NULL', 'i', [$targetUserId]);
        if (!$target) {
            flash(tr('flash.admin.user_not_found'), 'danger');
            redirect('/?page=admin_users');
        }
        $email = strtolower(trim((string) ($_POST['email'] ?? '')));
        $firstName = trim((string) ($_POST['first_name'] ?? ''));
        $lastName = trim((string) ($_POST['last_name'] ?? ''));
        if (!filter_var($email, FILTER_VALIDATE_EMAIL) || $firstName === '' || $lastName === '') {
            flash(tr('flash.admin.user_required'), 'danger');
            redirect('/?page=admin_users');
        }
        $status = in_array($_POST['status'] ?? '', ['invited','active','locked','disabled'], true) ? (string) $_POST['status'] : (string) $target['status'];
        try {
            $stmt = $db->prepare('UPDATE users SET email=?, first_name=?, last_name=?, status=?, email_verified_at=CASE WHEN ?="active" THEN COALESCE(email_verified_at, NOW()) ELSE email_verified_at END WHERE id=?');
            $stmt->bind_param('sssssi', $email, $firstName, $lastName, $status, $status, $targetUserId);
            $stmt->execute();
        } catch (mysqli_sql_exception) {
            flash(tr('flash.admin.email_taken'), 'danger');
            redirect('/?page=admin_users');
        }

        $adminRole = dbOne($db, "SELECT id FROM roles WHERE code='admin' LIMIT 1");
        $isAdminTarget = !empty($_POST['is_admin']);
        if ($adminRole) {
            $roleId = (int) $adminRole['id'];
            if ($isAdminTarget) {
                $stmt = $db->prepare('INSERT IGNORE INTO user_roles (user_id, role_id, assigned_by) VALUES (?, ?, ?)');
                $uid = realUserId();
                $stmt->bind_param('iii', $targetUserId, $roleId, $uid);
                $stmt->execute();
            } else {
                $stmt = $db->prepare('DELETE FROM user_roles WHERE user_id=? AND role_id=?');
                $stmt->bind_param('ii', $targetUserId, $roleId);
                $stmt->execute();
            }
        }
        audit($db, realUserId(), 'update', 'user', $targetUserId, $target, ['email' => $email, 'first_name' => $firstName, 'last_name' => $lastName, 'status' => $status, 'is_admin' => $isAdminTarget]);
        flash(tr('flash.admin.user_updated'));
        redirect('/?page=admin_users');
    }

    if ($action === 'admin_reset_user_password') {
        if (!isAdmin($db, realUserId(), $config)) {
            http_response_code(403);
            exit('Forbidden');
        }
        $targetUserId = (int) ($_POST['user_id'] ?? 0);
        if ($targetUserId === realUserId()) {
            flash(tr('flash.admin.own_password_reset_blocked'), 'warning');
            redirect('/?page=admin_users');
        }
        $target = dbOne($db, 'SELECT id, email, status FROM users WHERE id=? AND deleted_at IS NULL', 'i', [$targetUserId]);
        $password = (string) ($_POST['new_password'] ?? '');
        $confirm = (string) ($_POST['new_password_confirm'] ?? '');
        if (!$target || strlen($password) < 10 || $password !== $confirm) {
            flash(tr('flash.admin.password_reset_invalid'), 'danger');
            redirect('/?page=admin_users');
        }
        $hash = password_hash($password, PASSWORD_DEFAULT);
        $stmt = $db->prepare('UPDATE users SET password_hash=?, failed_login_count=0, locked_until=NULL WHERE id=?');
        $stmt->bind_param('si', $hash, $targetUserId);
        $stmt->execute();
        $stmt = $db->prepare("UPDATE auth_tokens SET consumed_at=NOW() WHERE user_id=? AND token_type='password_reset' AND consumed_at IS NULL");
        $stmt->bind_param('i', $targetUserId);
        $stmt->execute();
        audit($db, realUserId(), 'update', 'user', $targetUserId, ['admin_password_reset' => true], ['target_email' => $target['email']]);
        flash(tr('flash.admin.password_reset'));
        redirect('/?page=admin_users');
    }

    if ($action === 'admin_delete_user') {
        if (!isAdmin($db, realUserId(), $config)) {
            http_response_code(403);
            exit('Forbidden');
        }
        $targetUserId = (int) ($_POST['user_id'] ?? 0);
        if ($targetUserId === realUserId()) {
            flash(tr('flash.admin.own_delete_blocked'), 'warning');
            redirect('/?page=admin_users');
        }
        $target = dbOne($db, 'SELECT id, email, status FROM users WHERE id=? AND deleted_at IS NULL', 'i', [$targetUserId]);
        if (!$target) {
            flash(tr('flash.admin.user_not_found'), 'danger');
            redirect('/?page=admin_users');
        }
        $adminEmails = array_map('strtolower', (array) ($config['admin_emails'] ?? ['admin@jema.business']));
        if (in_array(strtolower((string) $target['email']), $adminEmails, true)) {
            flash(tr('flash.admin.config_delete_blocked'), 'warning');
            redirect('/?page=admin_users');
        }
        cleanupUserCascade($db, $targetUserId);
        $stmt = $db->prepare('UPDATE users SET deleted_at=NOW(), status="disabled" WHERE id=?');
        $stmt->bind_param('i', $targetUserId);
        $stmt->execute();
        $stmt = $db->prepare('UPDATE auth_tokens SET consumed_at=NOW() WHERE user_id=? AND consumed_at IS NULL');
        $stmt->bind_param('i', $targetUserId);
        $stmt->execute();
        audit($db, realUserId(), 'delete', 'user', $targetUserId, $target, ['soft_delete' => true]);
        flash(tr('flash.admin.user_deleted'));
        redirect('/?page=admin_users');
    }

    if ($action === 'admin_reset_user_2fa') {
        if (!isAdmin($db, realUserId(), $config)) {
            http_response_code(403);
            exit('Forbidden');
        }
        $targetUserId = (int) ($_POST['user_id'] ?? 0);
        if ($targetUserId === realUserId()) {
            flash(tr('flash.admin.own_2fa_reset_blocked'), 'warning');
            redirect('/?page=admin_users');
        }
        $target = dbOne($db, 'SELECT id, email FROM users WHERE id=? AND deleted_at IS NULL', 'i', [$targetUserId]);
        if (!$target) {
            flash(tr('flash.admin.user_not_found'), 'danger');
            redirect('/?page=admin_users');
        }
        $stmt = $db->prepare('DELETE FROM two_factor_methods WHERE user_id=?');
        $stmt->bind_param('i', $targetUserId);
        $stmt->execute();
        $stmt = $db->prepare("UPDATE auth_tokens SET consumed_at=NOW() WHERE user_id=? AND token_type='two_factor' AND consumed_at IS NULL");
        $stmt->bind_param('i', $targetUserId);
        $stmt->execute();
        audit($db, realUserId(), 'delete', 'user', $targetUserId, ['two_factor_reset' => true], ['target_email' => $target['email']]);
        flash(tr('flash.admin.two_factor_reset'));
        redirect('/?page=admin_users');
    }

    if ($action === 'enable_totp') {
        $code = (string) ($_POST['totp_code'] ?? '');
        $secret = (string) ($_SESSION['totp_setup_secret'] ?? '');
        if ($secret === '' || !verifyTotpCode($secret, $code)) {
            flash(tr('profile.totp_code_mismatch'), 'danger');
            redirect('/?page=profile#security');
        }
        $uid = userId();
        $stmt = $db->prepare("DELETE FROM two_factor_methods WHERE user_id=? AND method='totp'");
        $stmt->bind_param('i', $uid);
        $stmt->execute();
        $label = 'Authenticator-App';
        $stmt = $db->prepare("INSERT INTO two_factor_methods (user_id, method, label, secret_encrypted, is_primary, verified_at) VALUES (?, 'totp', ?, ?, 1, NOW())");
        $stmt->bind_param('iss', $uid, $label, $secret);
        $stmt->execute();
        unset($_SESSION['totp_setup_secret']);
        audit($db, $uid, 'create', 'user', $uid, null, ['two_factor' => 'totp']);
        flash(tr('profile.totp_enabled'));
        redirect('/?page=profile#security');
    }

    if ($action === 'disable_totp') {
        $uid = userId();
        $stmt = $db->prepare("DELETE FROM two_factor_methods WHERE user_id=? AND method='totp'");
        $stmt->bind_param('i', $uid);
        $stmt->execute();
        unset($_SESSION['totp_setup_secret']);
        audit($db, $uid, 'delete', 'user', $uid, ['two_factor' => 'totp'], null);
        flash(tr('profile.totp_disabled'));
        redirect('/?page=profile#security');
    }

    if ($action === 'create_share') {
        $shareTarget = (string) ($_POST['share_target'] ?? 'area');
        if ($shareTarget === 'area') {
            $targetType = 'area';
            $targetId = null;
        } elseif (preg_match('/^(job|application|document):(\d+)$/', $shareTarget, $targetMatches)) {
            $targetType = $targetMatches[1];
            $targetId = (int) $targetMatches[2];
        } else {
            $targetType = in_array($_POST['target_type'] ?? '', ['area','company','job','application','contact','document','report'], true) ? (string) $_POST['target_type'] : 'area';
            $targetId = $targetType === 'area' ? null : max(1, (int) ($_POST['target_id'] ?? 0));
        }
        $recipient = strtolower(trim((string) ($_POST['recipient_email'] ?? '')));
        $permission = in_array($_POST['permission'] ?? '', ['view','comment','edit'], true) ? (string) $_POST['permission'] : 'view';
        $downloadPolicy = in_array($_POST['download_policy'] ?? '', ['none','original','pdf','both'], true) ? (string) $_POST['download_policy'] : 'none';
        $title = trim((string) ($_POST['title'] ?? '')) ?: 'Freigabe';
        $expiresAt = trim((string) ($_POST['expires_at'] ?? '')) ?: null;
        if (!filter_var($recipient, FILTER_VALIDATE_EMAIL) || ($targetType !== 'area' && (!$targetId || !translationTargetExists($db, userId(), $targetType, (int)$targetId)))) {
            flash(tr('flash.sharing.required'), 'danger');
            redirect('/?page=sharing');
        }
        if ($expiresAt) {
            $expiresAt = str_replace('T', ' ', $expiresAt) . (strlen($expiresAt) === 16 ? ':00' : '');
        }
        $token = shareToken();
        $hash = shareTokenHash($token);
        $watermark = !empty($_POST['watermark_enabled']) ? 1 : 0;
        $uid = userId();
        $stmt = $db->prepare('INSERT INTO guest_shares (owner_user_id, token_hash, title, target_type, target_id, recipient_email, permission, download_policy, watermark_enabled, expires_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)');
        $stmt->bind_param('isssisssis', $uid, $hash, $title, $targetType, $targetId, $recipient, $permission, $downloadPolicy, $watermark, $expiresAt);
        $stmt->execute();
        $shareId = (int) $stmt->insert_id;
        $link = absoluteUrl($config, '/?page=guest&token=' . urlencode($token));
        $_SESSION['last_share_link'] = $link;
        $subject = 'JeMa Jobs Freigabe';
        $body = "Hallo\n\nes wurde ein JeMa Jobs Bereich für dich freigegeben:\n" . $link . "\n\nDiese Freigabe ist persönlich und kann widerrufen werden.\n";
        try {
            if (sendConfiguredMail($db, $config, $uid, $recipient, $subject, $body)) {
                flash(tr('flash.sharing.created_sent'));
            } else {
                flash(tr('flash.sharing.created_no_smtp'), 'warning');
            }
        } catch (Throwable) {
            flash(tr('flash.sharing.created_mail_failed'), 'warning');
        }
        audit($db, $uid, 'create', 'guest_share', $shareId, null, ['target_type' => $targetType, 'target_id' => $targetId, 'recipient_email' => $recipient]);
        redirect('/?page=sharing');
    }

    if ($action === 'revoke_share') {
        $id = (int) ($_POST['share_id'] ?? 0);
        $old = dbOne($db, 'SELECT * FROM guest_shares WHERE id=? AND owner_user_id=? AND revoked_at IS NULL', 'ii', [$id, userId()]);
        if ($old) {
            $stmt = $db->prepare('UPDATE guest_shares SET revoked_at=NOW() WHERE id=? AND owner_user_id=?');
            $uid = userId();
            $stmt->bind_param('ii', $id, $uid);
            $stmt->execute();
            audit($db, $uid, 'delete', 'guest_share', $id, $old, ['revoked' => true]);
            flash(tr('flash.sharing.revoked'));
        }
        redirect('/?page=sharing');
    }

    if ($action === 'save_translation') {
        $target = (string) ($_POST['translation_target'] ?? '');
        if (preg_match('/^(company|job|contact|application|document):(\d+)$/', $target, $matches)) {
            $entityType = $matches[1];
            $entityId = (int) $matches[2];
        } else {
            $entityType = in_array($_POST['entity_type'] ?? '', ['company','job','contact','application','document'], true) ? (string) $_POST['entity_type'] : '';
            $entityId = max(0, (int) ($_POST['entity_id'] ?? 0));
        }
        $targetLanguage = normalizeLocale((string) ($_POST['target_language'] ?? 'de-CH'));
        $title = trim((string) ($_POST['translation_title'] ?? '')) ?: null;
        $body = trim((string) ($_POST['translation_body'] ?? ''));
        $uid = userId();
        if ($body === '' || $entityType === '' || $entityId < 1 || !translationTargetExists($db, $uid, $entityType, $entityId)) {
            flash(tr('flash.translation.required'), 'danger');
            redirect('/?page=translations');
        }
        $existing = dbOne($db, 'SELECT COALESCE(MAX(version),0) v FROM record_translations WHERE owner_user_id=? AND entity_type=? AND entity_id=? AND target_language=?', 'isis', [$uid, $entityType, $entityId, $targetLanguage]);
        $version = (int) ($existing['v'] ?? 0) + 1;
        $stmt = $db->prepare('UPDATE record_translations SET is_current=0 WHERE owner_user_id=? AND entity_type=? AND entity_id=? AND target_language=?');
        $stmt->bind_param('isis', $uid, $entityType, $entityId, $targetLanguage);
        $stmt->execute();
        $stmt = $db->prepare('INSERT INTO record_translations (owner_user_id, entity_type, entity_id, target_language, title, body, version, is_current) VALUES (?, ?, ?, ?, ?, ?, ?, 1)');
        $stmt->bind_param('isisssi', $uid, $entityType, $entityId, $targetLanguage, $title, $body, $version);
        $stmt->execute();
        audit($db, $uid, 'create', 'record_translation', (int) $stmt->insert_id, null, ['entity_type' => $entityType, 'entity_id' => $entityId, 'target_language' => $targetLanguage, 'version' => $version]);
        flash(tr('flash.translation.saved'));
        redirect('/?page=translations');
    }

    if ($action === 'prepare_translation') {
        $target = (string) ($_POST['translation_target'] ?? '');
        $targetLanguage = normalizeLocale((string) ($_POST['target_language'] ?? 'de-CH'));
        if (!preg_match('/^(company|job|contact|application|document):(\d+)$/', $target, $matches)) {
            flash(tr('flash.translation.select_record'), 'danger');
            redirect('/?page=translations');
        }
        $entityType = $matches[1];
        $entityId = (int) $matches[2];
        $uid = userId();
        if (!translationTargetExists($db, $uid, $entityType, $entityId)) {
            flash(tr('flash.translation.record_unavailable'), 'danger');
            redirect('/?page=translations');
        }
        $source = translationSource($db, $uid, $entityType, $entityId, $currentUser ?? []);
        if (trim((string)$source['source']) === '') {
            flash(tr('flash.translation.no_source'), 'warning');
            redirect('/?page=translations');
        }
        $_SESSION['translation_draft'] = [
            'target' => $target,
            'target_language' => $targetLanguage,
            'title' => trim((string) ($_POST['translation_title'] ?? '')) ?: (string)$source['title'],
            'body' => translationPrompt($targetLanguage, (string)$source['title'], (string)$source['source']),
        ];
        flash(tr('flash.translation.prepared'));
        redirect('/?page=translations#translation-form');
    }

    if (in_array($action, ['save_calendar_event','update_calendar_event'], true)) {
        $uid = userId();
        $eventId = $action === 'update_calendar_event' ? (int)($_POST['event_id'] ?? 0) : 0;
        $event = $eventId > 0 ? calendarLocalEvent($db,$uid,$eventId) : null;
        if ($action === 'update_calendar_event' && (!$event || ($event['entry_kind'] ?? '') === 'milestone')) {
            http_response_code(404); exit('Not found');
        }
        $applicationId = (int)($_POST['application_id'] ?? 0) ?: null;
        $application = $applicationId ? dbOne($db,'SELECT id, job_id, status FROM applications WHERE id=? AND user_id=? AND deleted_at IS NULL','ii',[$applicationId,$uid]) : null;
        if ($applicationId && !$application) { http_response_code(404); exit('Not found'); }
        $requestId = (string)($_POST['event_request_id'] ?? '');
        if (!$eventId) {
            if (!array_key_exists($requestId,$_SESSION['calendar_requests'] ?? [])) { http_response_code(409); exit(tr('workflow.changed')); }
            if (!empty($_SESSION['calendar_requests'][$requestId])) { redirect('/?page=calendar&view=agenda'); }
        }
        $eventType = array_key_exists((string)($_POST['event_type'] ?? ''),calendarEventTypeOptions()) ? (string)$_POST['event_type'] : 'other';
        $title = trim((string)($_POST['event_title'] ?? ''));
        if ($title === '' && in_array($eventType,['follow_up','interview'],true)) { $title = calendarEventTypeOptions()[$eventType]; }
        try {
            if ($title === '') { throw new InvalidArgumentException(tr('flash.calendar.required')); }
            [$startsAt,$endsAt] = workflowCalendarRange((string)($_POST['starts_at'] ?? ''),(string)($_POST['ends_at'] ?? ''));
        } catch (InvalidArgumentException $exception) {
            flash($exception->getMessage(),'danger');
            redirect('/?page=calendar&application_id='.(int)$applicationId.'&new_type='.urlencode($eventType).'#calendar-entry-form');
        }
        $status = array_key_exists((string)($_POST['event_status'] ?? ''),calendarStatusOptions()) ? (string)$_POST['event_status'] : 'planned';
        $notes = trim((string)($_POST['event_notes'] ?? '')) ?: null;
        $location = trim((string)($_POST['event_location'] ?? '')) ?: null;
        $allDay = $event && !empty($event['all_day']) && dbOne($db,'SELECT calendar_event_id FROM google_calendar_import_links WHERE user_id=? AND calendar_event_id=?','ii',[$uid,$eventId]) ? 1 : 0;
        $db->begin_transaction();
        try {
            if ($eventId) {
                $stmt = $db->prepare("UPDATE calendar_events SET application_id=?, title=?, event_type=?, starts_at=?, ends_at=?, all_day=?, status=?, location=?, notes=?, completed_at=CASE WHEN ? IN ('completed','cancelled') THEN COALESCE(completed_at,NOW()) ELSE NULL END WHERE id=? AND owner_user_id=?");
                $stmt->bind_param('issssissssii',$applicationId,$title,$eventType,$startsAt,$endsAt,$allDay,$status,$location,$notes,$status,$eventId,$uid);
            } else {
                $stmt = $db->prepare("INSERT INTO calendar_events (owner_user_id,application_id,title,event_type,entry_kind,starts_at,ends_at,all_day,status,location,notes,completed_at) VALUES (?,?,?,?,'appointment',?,?,?,?,?,?,CASE WHEN ? IN ('completed','cancelled') THEN NOW() ELSE NULL END)");
                $stmt->bind_param('iissssissss',$uid,$applicationId,$title,$eventType,$startsAt,$endsAt,$allDay,$status,$location,$notes,$status);
            }
            $stmt->execute();
            if (!$eventId) { $eventId = (int)$stmt->insert_id; }
            if ($application && $eventType === 'interview' && in_array($status,['planned','completed'],true)) {
                $locked = dbOne($db,'SELECT status FROM applications WHERE id=? AND user_id=? FOR UPDATE','ii',[$applicationId,$uid]);
                if ($locked && in_array($locked['status'],['sent','confirmed'],true)) {
                    cascadeExec($db,"UPDATE applications SET status='interview', job_room_interview=1 WHERE id=? AND user_id=?",'ii',[$applicationId,$uid]);
                    cascadeExec($db,"INSERT INTO application_status_history (application_id,changed_by,old_status,new_status) VALUES (?,?,?,'interview')",'iis',[$applicationId,$uid,$locked['status']]);
                    cascadeExec($db,"UPDATE jobs SET status='interview' WHERE id=? AND owner_user_id=?",'ii',[(int)$application['job_id'],$uid]);
                }
            }
            audit($db,$uid,$action==='save_calendar_event'?'create':'update','calendar_event',$eventId,null,['title'=>$title,'starts_at'=>$startsAt,'application_id'=>$applicationId]);
            $db->commit();
        } catch (Throwable $exception) { $db->rollback(); throw $exception; }
        if ($requestId !== '') { $_SESSION['calendar_requests'][$requestId] = $eventId; }
        $savedEvent = calendarLocalEvent($db,$uid,$eventId);
        if ($event && $savedEvent) {
            try { syncImportedCalendarEvent($db,$config,$uid,$currentUser ?? [],$savedEvent); }
            catch (Throwable $exception) { error_log('Imported calendar sync failed: '.$exception->getMessage()); }
        }
        syncCalendarAutomatically($db,$config,$uid,$currentUser ?? []);
        flash(tr('flash.calendar.saved'));
        redirect('/?page=calendar&view=agenda&date='.substr($startsAt,0,10));
    }

    if ($action === 'delete_calendar_event') {
        $uid = userId();
        $eventId = (int) ($_POST['event_id'] ?? 0);
        $deleteEvent = calendarLocalEvent($db, $uid, $eventId);
        if ($deleteEvent && ($deleteEvent['entry_kind'] ?? '') !== 'milestone') {
            try {
                deleteGoogleCalendarEvent($db, $config, $uid, $currentUser ?? [], $eventId);
            } catch (Throwable $exception) {
                error_log('Google calendar event deletion failed: ' . $exception->getMessage());
            }
            $stmt = $db->prepare("UPDATE calendar_events SET status='cancelled', completed_at=NOW() WHERE id=? AND owner_user_id=?");
            $stmt->bind_param('ii', $eventId, $uid);
            $stmt->execute();
            syncCalendarAutomatically($db, $config, $uid, $currentUser ?? []);
            audit($db, $uid, 'delete', 'calendar_event', $eventId, null, null);
            flash(tr('flash.calendar.deleted'));
        }
        redirect('/?page=calendar&view=agenda');
    }

    if ($action === 'rotate_calendar_feed') {
        $uid = userId();
        rotateCalendarFeed($db, $uid);
        audit($db, $uid, 'update', 'user_calendar_feed', $uid, null, ['rotated' => true]);
        flash(tr('flash.calendar_feed.rotated'));
        redirect('/?page=profile#calendar-sync');
    }

    if ($action === 'connect_google_calendar') {
        $uid = userId();
        $credentials = googleCalendarAppCredentials($config);
        if ($credentials['client_id'] === '' || $credentials['client_secret'] === '') {
            flash(tr('flash.google_calendar.credentials_required'), 'danger');
            redirect('/?page=profile#calendar-sync');
        }
        $calendarId = 'primary';
        $syncEnabled = 1;
        $stmt = $db->prepare('INSERT INTO user_google_calendar_settings (user_id, calendar_id, sync_enabled) VALUES (?, ?, ?) ON DUPLICATE KEY UPDATE calendar_id=VALUES(calendar_id), sync_enabled=VALUES(sync_enabled), updated_at=NOW()');
        $stmt->bind_param('isi', $uid, $calendarId, $syncEnabled);
        $stmt->execute();
        audit($db, $uid, 'update', 'google_calendar_settings', $uid, null, ['calendar_id' => $calendarId, 'sync_enabled' => $syncEnabled]);
        $state = bin2hex(random_bytes(24));
        $_SESSION['google_oauth_state'] = $state;
        $_SESSION['google_oauth_return_page'] = 'profile';
        redirect(googleCalendarAuthUrl($config, $credentials['client_id'], $state));
    }

    if ($action === 'select_google_calendar') {
        $uid = userId();
        $settings = googleCalendarSettings($db, $uid);
        if (empty($settings['refresh_token_encrypted'])) {
            flash(tr('flash.google_calendar.credentials_required'), 'danger');
            redirect('/?page=profile#calendar-sync');
        }
        $calendarId = trim((string) ($_POST['google_calendar_id'] ?? '')) ?: 'primary';
        $calendarSummary = $calendarId;
        try {
            $token = googleAccessToken($db, $config, $uid, $settings);
            $calendar = googleJsonRequest('GET', 'https://www.googleapis.com/calendar/v3/calendars/' . rawurlencode($calendarId), ['Authorization: Bearer ' . $token]);
            $calendarSummary = trim((string) ($calendar['summary'] ?? $calendarSummary));
        } catch (Throwable $ignored) {
            // Die Auswahl bleibt auch dann erhalten, wenn Google den Anzeigenamen nicht liefert.
        }
        $stmt = $db->prepare('UPDATE user_google_calendar_settings SET calendar_id=?, calendar_summary=?, sync_enabled=1, updated_at=NOW() WHERE user_id=?');
        $stmt->bind_param('ssi', $calendarId, $calendarSummary, $uid);
        $stmt->execute();
        audit($db, $uid, 'update', 'google_calendar_settings', $uid, null, ['calendar_id' => $calendarId]);
        flash(tr('flash.google_calendar.config_saved'));
        redirect('/?page=profile#calendar-sync');
    }

    if ($action === 'sync_google_calendar') {
        $uid = userId();
        try {
            $result = syncGoogleCalendarEvents($db, $config, $uid, $currentUser ?? []);
            audit($db, $uid, 'update', 'google_calendar_sync', $uid, null, $result);
            flash(tr('flash.google_calendar.sync_done', null, [
                'created' => (string) $result['created'],
                'updated' => (string) $result['updated'],
                'failed' => (string) $result['failed'],
            ]), ((int) $result['failed'] > 0 ? 'warning' : 'success'));
        } catch (Throwable $exception) {
            flash(tr('flash.google_calendar.oauth_failed', null, ['error' => $exception->getMessage()]), 'danger');
        }
        redirect('/?page=profile#calendar-sync');
    }

    if ($action === 'disconnect_google_calendar') {
        $uid = userId();
        $stmt = $db->prepare('UPDATE user_google_calendar_settings SET access_token_encrypted=NULL, refresh_token_encrypted=NULL, token_expires_at=NULL, sync_enabled=0, last_error=NULL, updated_at=NOW() WHERE user_id=?');
        $stmt->bind_param('i', $uid);
        $stmt->execute();
        $stmt = $db->prepare('DELETE FROM google_calendar_event_links WHERE user_id=?');
        $stmt->bind_param('i', $uid);
        $stmt->execute();
        audit($db, $uid, 'update', 'google_calendar_settings', $uid, null, ['disconnected' => true]);
        flash(tr('flash.google_calendar.disconnected'));
        redirect('/?page=profile#calendar-sync');
    }

    if ($action === 'save_report') {
        $name = trim((string) ($_POST['report_name'] ?? ''));
        $description = trim((string) ($_POST['report_description'] ?? '')) ?: null;
        $baseEntity = array_key_exists((string) ($_POST['base_entity'] ?? ''), reportBaseOptions()) ? (string) $_POST['base_entity'] : 'jobs';
        $displayType = array_key_exists((string) ($_POST['display_type'] ?? ''), reportDisplayOptions()) ? (string) $_POST['display_type'] : 'table';
        if ($name === '') {
            flash(tr('flash.reports.name_required'), 'danger');
            redirect('/?page=reports');
        }
        $uid = userId();
