            http_response_code(404);
            exit('Not found');
        }
        $documents = dbAll($db, 'SELECT id FROM user_documents WHERE user_id=? AND job_id=? AND title="Originale Stellenausschreibung" AND deleted_at IS NULL', 'ii', [$uid, $id]);
        $db->begin_transaction();
