        $occurredAt = trim((string) ($_POST['mail_occurred_at'] ?? '')) ?: date('Y-m-d H:i:s');
        $followUpAt = null;
        $occurredAt = str_replace('T', ' ', $occurredAt) . (strlen($occurredAt) === 16 ? ':00' : '');
        if ($followUpAt) {
            $followUpAt = str_replace('T', ' ', $followUpAt) . (strlen($followUpAt) === 16 ? ':00' : '');
        }
        $logStatus = $followUpAt ? 'open' : 'done';
        $outcome = $logApplicationId > 0 ? tr('mail_activity.application_reply_logged') : tr('mail_activity.email_logged');
        $stmt = $db->prepare('INSERT INTO contact_logs (owner_user_id, contact_id, company_id, application_id, job_id, channel, direction, status, subject, body, occurred_at, follow_up_at, outcome) VALUES (?, ?, ?, NULLIF(?,0), NULLIF(?,0), ?, ?, ?, ?, ?, ?, ?, ?)');
        $stmt->bind_param('iiiiissssssss', $uid, $contactId, $companyId, $logApplicationId, $jobId, $channel, $direction, $logStatus, $subject, $body, $occurredAt, $followUpAt, $outcome);
        $stmt->execute();
        $logId = (int) $stmt->insert_id;
        try {
            saveContactLogAttachment($db, $uid, $contactId, $logId, trim((string)$contact['first_name'] . ' ' . (string)$contact['last_name']), $subject);
        } catch (Throwable $exception) {
            flash(strtr(tr('flash.contact_log.saved_attachment_failed'), ['{error}' => $exception->getMessage()]), 'warning');
            redirect($returnTo . '#mail-activity');
        }
        syncContactLogFollowUp($db, $uid, $logId);
        $newStatus = trim((string) ($_POST['mail_application_status'] ?? ''));
        if ($application && $newStatus !== '' && array_key_exists($newStatus, applicationStatusOptions(false)) && $newStatus !== (string) $application['status']) {
            $appliedAt = null;
            $nextAction = null;
            $nextActionAt = null;
            if ($newStatus === 'sent') {
                $appliedAt = $occurredAt;
                $nextAction = null;
                $nextActionAt = null;
            }
            $stmt = $db->prepare('UPDATE applications SET status=?, applied_at=COALESCE(applied_at, ?), next_action=?, next_action_at=? WHERE id=? AND user_id=?');
            $stmt->bind_param('ssssii', $newStatus, $appliedAt, $nextAction, $nextActionAt, $logApplicationId, $uid);
            $stmt->execute();
            $history = $db->prepare('INSERT INTO application_status_history (application_id, changed_by, old_status, new_status, comment) VALUES (?, ?, ?, ?, ?)');
            $oldStatus = (string) $application['status'];
            $comment = tr('mail_activity.status_changed_by_mail');
            $history->bind_param('iisss', $logApplicationId, $uid, $oldStatus, $newStatus, $comment);
            $history->execute();
        }
        if ($logApplicationId > 0) {
            syncApplicationWorkflow($db, $uid, $logApplicationId);
        }
        audit($db, $uid, 'create', 'mail_activity', $logId, null, ['contact_id' => $contactId, 'company_id' => $companyId, 'application_id' => $logApplicationId, 'direction' => $direction, 'subject' => $subject]);
        flash(tr('mail_activity.saved'));
        redirect($returnTo . '#mail-activity');
    }

    if ($action === 'complete_application_action') { redirect('/?page=calendar&view=agenda'); }

    if ($action === 'revise_application_texts_ai') {
        $id=(int)($_POST['id'] ?? 0); $uid=userId();
        $application=dbOne($db,'SELECT id FROM applications WHERE id=? AND user_id=? AND deleted_at IS NULL','ii',[$id,$uid]);
        if (!$application) { http_response_code(404); exit('Not found'); }
        $currentTexts=[
            'email_subject'=>mb_substr(trim((string)($_POST['email_subject'] ?? '')),0,255),
            'email_body'=>mb_substr(trim((string)($_POST['email_body'] ?? '')),0,20000),
            'cover_letter_text'=>mb_substr(trim((string)($_POST['cover_letter_text'] ?? '')),0,40000),
        ];
        try {
            $texts=applicationAiTexts($config,$db,$uid,$id,$currentUser ?? [],(string)($_POST['ai_text_instruction'] ?? ''),$currentTexts);
            $stmt=$db->prepare('UPDATE applications SET email_subject=?, email_body=?, cover_letter_text=? WHERE id=? AND user_id=?');
            $stmt->bind_param('sssii',$texts['email_subject'],$texts['email_body'],$texts['cover_letter_text'],$id,$uid); $stmt->execute();
            audit($db,$uid,'update','application_ai_texts',$id,null,['fields'=>['email_subject','email_body','cover_letter_text']]);
            flash(tr('applications.ai_updated'));
        } catch (Throwable $exception) {
            error_log('Application AI revision failed for application '.$id.': '.$exception->getMessage());
            flash(tr('applications.ai_failed'),'danger');
        }
        redirect('/?page=applications&edit='.$id.'#application-texts');
    }

    if (in_array($action, ['save_application', 'autosave_application'], true)) {
        $isAutosave = $action === 'autosave_application';
        $id = (int) ($_POST['id'] ?? 0);
        $db->begin_transaction();
        try {
        $old = dbOne($db, 'SELECT id, job_id, intermediary_company_id, primary_contact_id, status, applied_at, next_action, next_action_at FROM applications WHERE id=? AND user_id=? AND deleted_at IS NULL FOR UPDATE', 'ii', [$id, userId()]);
        if (!$old) { http_response_code(404); exit('Not found'); }
        $allowedStatuses = array_unique(array_merge(applicationStatusSequence(), [(string)$old['status']]));
        $allowedChannels = ['email','portal','website','mail','referral','other'];
        $status = in_array($_POST['status'] ?? '', $allowedStatuses, true) ? (string) $_POST['status'] : (string)$old['status'];
        $channel = in_array($_POST['channel'] ?? '', $allowedChannels, true) ? (string) $_POST['channel'] : null;
        $appliedAt = trim((string) ($_POST['applied_at'] ?? '')) ?: null;
        $nextAction = $old['next_action'];
        $nextActionAt = $old['next_action_at'];
        $emailSubject = trim((string) ($_POST['email_subject'] ?? '')) ?: null;
        $emailBody = trim((string) ($_POST['email_body'] ?? '')) ?: null;
        $applicationUrl = trim((string) ($_POST['application_url'] ?? '')) ?: null;
        if ($applicationUrl !== null && !filter_var($applicationUrl, FILTER_VALIDATE_URL)) {
            if ($isAutosave) {
                header('Content-Type: application/json; charset=utf-8');
                http_response_code(422);
                echo json_encode(['ok' => false, 'message' => tr('applications.online_url_invalid')], JSON_UNESCAPED_UNICODE);
                exit;
            }
            flash(tr('applications.online_url_invalid'), 'danger');
            redirect('/?page=applications&edit=' . $id . '#application-form');
        }
        $portalAccount = trim((string) ($_POST['portal_account'] ?? '')) ?: null;
        $referenceNumber = trim((string) ($_POST['reference_number'] ?? '')) ?: null;
        $onlineNotes = trim((string) ($_POST['online_notes'] ?? '')) ?: null;
        $coverLetter = trim((string) ($_POST['cover_letter_text'] ?? '')) ?: null;
        $notes = trim((string) ($_POST['notes'] ?? '')) ?: null;
        $allowedJobRoomResults = ['open', 'hired', 'rejected'];
        $jobRoomResult = in_array((string)($_POST['job_room_result'] ?? ''), $allowedJobRoomResults, true)
            ? (string)$_POST['job_room_result']
            : 'open';
        $jobRoomInterview = isset($_POST['job_room_interview']) ? 1 : 0;
        $jobRoomRegistration = in_array($_POST['job_room_registration'] ?? '', ['unknown','not_recorded','recorded'], true) ? (string)$_POST['job_room_registration'] : null;
        $primaryContactId = (int) ($_POST['primary_contact_id'] ?? 0);
        $intermediaryCompanyId = (int) ($_POST['intermediary_company_id'] ?? 0);
        if ($intermediaryCompanyId > 0) {
            $jobCompany = dbOne($db, 'SELECT company_id FROM jobs WHERE id=? AND owner_user_id=? AND deleted_at IS NULL', 'ii', [(int)$old['job_id'], userId()]);
            $intermediary = dbOne($db, 'SELECT id FROM companies WHERE id=? AND owner_user_id=? AND is_intermediary=1 AND deleted_at IS NULL', 'ii', [$intermediaryCompanyId, userId()]);
            if (!$jobCompany || !$intermediary || $intermediaryCompanyId === (int)$jobCompany['company_id']) {
                $intermediaryCompanyId = 0;
            } else {
                $relationship = $db->prepare("INSERT INTO company_relationships (owner_user_id, intermediary_company_id, client_company_id, relationship_type) VALUES (?, ?, ?, 'recruitment_agency') ON DUPLICATE KEY UPDATE deleted_at=NULL, updated_at=NOW()");
                $uid = userId(); $clientCompanyId = (int)$jobCompany['company_id'];
                $relationship->bind_param('iii', $uid, $intermediaryCompanyId, $clientCompanyId);
                $relationship->execute();
            }
        }
        if ($primaryContactId > 0) {
            $validContact = dbOne($db, 'SELECT c.id FROM contacts c JOIN jobs j ON j.id=? WHERE c.id=? AND c.owner_user_id=? AND c.deleted_at IS NULL AND (c.company_id=j.company_id OR c.company_id=?)', 'iiii', [(int)$old['job_id'], $primaryContactId, userId(), $intermediaryCompanyId]);
            if (!$validContact) { $primaryContactId = 0; }
        }
        try {
            $appliedAt = applicationSentAt($old, $status, $appliedAt);
        } catch (InvalidArgumentException $exception) {
            if ($isAutosave) {
                header('Content-Type: application/json; charset=utf-8');
                http_response_code(422);
                echo json_encode(['ok'=>false,'message'=>$exception->getMessage()]);
                exit;
            }
            flash($exception->getMessage(), 'danger');
            redirect('/?page=applications&edit=' . $id . '#application-form');
        }
        $statusChanged = (string)$old['status'] !== $status;
        if ($statusChanged) {
            if (in_array($status, ['interview', 'assessment'], true)) {
                $jobRoomInterview = 1;
                $jobRoomResult = 'open';
            } elseif ($status === 'accepted') {
                $jobRoomResult = 'hired';
            } elseif ($status === 'rejected') {
                $jobRoomResult = 'rejected';
            }
        }
        // Retained legacy fields are only changed by the reviewed migration.
        $stmt = $db->prepare('UPDATE applications SET intermediary_company_id=NULLIF(?,0), primary_contact_id=NULLIF(?,0), status=?, channel=?, applied_at=?, next_action=?, next_action_at=?, application_url=?, portal_account=?, reference_number=?, online_notes=?, email_subject=?, email_body=?, cover_letter_text=?, notes=?, job_room_result=?, job_room_interview=? WHERE id=? AND user_id=?');
        $uid = userId();
        $applicationUpdateTypes = 'ii' . str_repeat('s', 14) . 'iii';
        $stmt->bind_param($applicationUpdateTypes, $intermediaryCompanyId, $primaryContactId, $status, $channel, $appliedAt, $nextAction, $nextActionAt, $applicationUrl, $portalAccount, $referenceNumber, $onlineNotes, $emailSubject, $emailBody, $coverLetter, $notes, $jobRoomResult, $jobRoomInterview, $id, $uid);
        $stmt->execute();
        if ($jobRoomRegistration !== null) {
            cascadeExec($db, 'UPDATE applications SET job_room_registration=? WHERE id=? AND user_id=?', 'sii', [$jobRoomRegistration, $id, $uid]);
        }
        if ($statusChanged) {
            $comment = trim((string) ($_POST['status_comment'] ?? '')) ?: null;
            $history = $db->prepare('INSERT INTO application_status_history (application_id, changed_by, old_status, new_status, comment) VALUES (?, ?, ?, ?, ?)');
            $history->bind_param('iisss', $id, $uid, $old['status'], $status, $comment);
            $history->execute();
            $jobStatus = ['sent'=>'applied','confirmed'=>'applied','interview'=>'interview','assessment'=>'interview','offer'=>'offer','accepted'=>'offer','rejected'=>'rejected','withdrawn'=>'closed','closed'=>'closed'][$status] ?? null;
            if ($jobStatus) {
                $jobStmt = $db->prepare('UPDATE jobs SET status=? WHERE id=? AND owner_user_id=?');
                $jobId = (int) $old['job_id'];
                $jobStmt->bind_param('sii', $jobStatus, $jobId, $uid);
                $jobStmt->execute();
            }
        }
        audit($db, $uid, 'update', 'application', $id, ['status' => $old['status']], ['status' => $status, 'channel' => $channel, 'application_url' => $applicationUrl, 'reference_number' => $referenceNumber, 'next_action' => $nextAction, 'next_action_at' => $nextActionAt]);
        if ($status === 'sent' && $primaryContactId > 0) {
            ensureSubmittedApplicationContactLog($db, $uid, $id);
        }
        syncApplicationWorkflow($db, $uid, $id);
        $db->commit();
        } catch (Throwable $exception) { $db->rollback(); throw $exception; }
        if ($statusChanged || ($old['applied_at'] ?? '') !== ($appliedAt ?? '') || ($old['next_action'] ?? '') !== ($nextAction ?? '') || ($old['next_action_at'] ?? '') !== ($nextActionAt ?? '')) {
            syncCalendarAutomatically($db, $config, $uid, $currentUser ?? []);
        }
        if ($isAutosave) {
            header('Content-Type: application/json; charset=utf-8');
            echo json_encode(['ok' => true, 'message' => tr('applications.autosave_saved'), 'applied_at' => $appliedAt, 'next_action' => $nextAction, 'next_action_at' => $nextActionAt], JSON_UNESCAPED_UNICODE);
            exit;
        }
        flash(tr('applications.saved'));
        redirect('/?page=applications&edit=' . $id . '#application-form');
    }

    if ($action === 'submit_online_application') {
        $id = (int) ($_POST['id'] ?? 0);
        $uid = userId();
        $sendLock = 'jema-send-' . $uid . '-' . $id;
        if ((int)(dbOne($db,'SELECT GET_LOCK(?,10) acquired','s',[$sendLock])['acquired'] ?? 0) !== 1) {
            flash(tr('workflow.changed'),'warning');
            redirect('/?page=applications&edit='.$id.'#application-form');
        }
        $db->begin_transaction();
        try {
        $old = dbOne($db, 'SELECT id, job_id, primary_contact_id, status, applied_at FROM applications WHERE id=? AND user_id=? AND deleted_at IS NULL FOR UPDATE', 'ii', [$id, $uid]);
        if (!$old) { http_response_code(404); exit('Not found'); }
        $applicationUrl = trim((string) ($_POST['application_url'] ?? '')) ?: null;
        if ($applicationUrl !== null && !filter_var($applicationUrl, FILTER_VALIDATE_URL)) {
            flash(tr('applications.online_url_invalid'), 'danger');
            redirect('/?page=applications&edit=' . $id . '#application-form');
        }
        if (!in_array($old['status'], ['draft','ready'], true) || !empty($old['applied_at'])) {
            flash(tr('workflow.already_sent'), 'warning');
            redirect('/?page=applications&edit=' . $id . '#application-form');
        }
        $appliedAt = date('Y-m-d H:i:s');
        $channel = in_array($_POST['channel'] ?? '', ['portal','website','other'], true) ? (string) $_POST['channel'] : 'website';
        $portalAccount = trim((string) ($_POST['portal_account'] ?? '')) ?: null;
        $referenceNumber = trim((string) ($_POST['reference_number'] ?? '')) ?: null;
        $onlineNotes = trim((string) ($_POST['online_notes'] ?? '')) ?: null;
        $coverLetter = trim((string) ($_POST['cover_letter_text'] ?? '')) ?: null;
        $notes = trim((string) ($_POST['notes'] ?? '')) ?: null;
        $primaryContactId = (int) ($_POST['primary_contact_id'] ?? 0);
        if ($primaryContactId > 0) {
            $validContact = dbOne($db, 'SELECT id FROM contacts WHERE id=? AND owner_user_id=? AND deleted_at IS NULL', 'ii', [$primaryContactId, $uid]);
            if (!$validContact) { $primaryContactId = 0; }
        }
        $status = 'sent';
        $stmt = $db->prepare("UPDATE applications SET primary_contact_id=NULLIF(?,0), status=?, channel=?, applied_at=?,
            next_action_at=CASE WHEN next_action IN ('send_application','await_response') THEN NULL ELSE next_action_at END,
            next_action=CASE WHEN next_action IN ('send_application','await_response') THEN NULL ELSE next_action END,
            application_url=?, portal_account=?, reference_number=?, online_notes=?, cover_letter_text=?, notes=? WHERE id=? AND user_id=?");
        $stmt->bind_param('isssssssssii', $primaryContactId, $status, $channel, $appliedAt, $applicationUrl, $portalAccount, $referenceNumber, $onlineNotes, $coverLetter, $notes, $id, $uid);
        $stmt->execute();
        if ((string)$old['status'] !== $status) {
            $history = $db->prepare('INSERT INTO application_status_history (application_id, changed_by, old_status, new_status, comment) VALUES (?, ?, ?, ?, ?)');
            $comment = 'Online-Bewerbung eingereicht';
            $oldStatus = (string) $old['status'];
            $history->bind_param('iisss', $id, $uid, $oldStatus, $status, $comment);
            $history->execute();
        }
        $jobStatus = 'applied';
        $jobId = (int) $old['job_id'];
        $jobStmt = $db->prepare('UPDATE jobs SET status=? WHERE id=? AND owner_user_id=?');
        $jobStmt->bind_param('sii', $jobStatus, $jobId, $uid);
        $jobStmt->execute();
        if ($primaryContactId > 0) {
            ensureSubmittedApplicationContactLog($db, $uid, $id);
        }
        ensureSubmittedApplicationCalendarEvent($db, $uid, $id);
        $db->commit();
        } catch (Throwable $exception) { $db->rollback(); throw $exception; }
        syncCalendarAutomatically($db, $config, $uid, $currentUser ?? []);
        audit($db, $uid, 'send', 'application', $id, ['status' => $old['status']], ['status' => $status, 'channel' => $channel, 'application_url' => $applicationUrl]);
        flash(tr('applications.online_submitted_logged'));
        redirect('/?page=applications&edit=' . $id . '#application-form');
    }

    if ($action === 'send_application_email') {
        $id = (int) ($_POST['id'] ?? 0);
        // Serialize submissions across sessions; the connection releases the lock on every exit path.
        $sendLock = 'jema-send-' . userId() . '-' . $id;
        if ((int)(dbOne($db,'SELECT GET_LOCK(?,10) acquired','s',[$sendLock])['acquired'] ?? 0) !== 1) {
            flash(tr('workflow.changed'),'warning');
            redirect('/?page=applications&edit='.$id.'#application-form');
        }
        $application = dbOne(
            $db,
            'SELECT a.id, a.primary_contact_id, a.email_subject, SUBSTRING(a.email_body,1,65535) email_body, a.status, j.title, c.name company_name, ct.email contact_email, ct.first_name contact_first_name, ct.last_name contact_last_name
               FROM applications a
               JOIN jobs j ON j.id=a.job_id
               JOIN companies c ON c.id=j.company_id
               LEFT JOIN contacts ct ON ct.id=a.primary_contact_id AND ct.owner_user_id=a.user_id AND ct.deleted_at IS NULL
              WHERE a.id=? AND a.user_id=? AND a.deleted_at IS NULL
              LIMIT 1',
            'ii',
            [$id, userId()]
        );
        if ($application && !in_array($application['status'], ['draft','ready'], true)) {
            flash(tr('workflow.already_sent'), 'warning');
            redirect('/?page=applications&edit=' . $id . '#application-form');
        }
        $hasAssignedContact = (int) ($application['primary_contact_id'] ?? 0) > 0;
        $recipient = $hasAssignedContact
            ? strtolower(trim((string) ($application['contact_email'] ?? '')))
            : strtolower(trim((string) ($_POST['recipient_email'] ?? '')));
        $subject = trim((string) ($_POST['email_subject'] ?? ($application['email_subject'] ?? '')));
        $body = trim((string) ($_POST['email_body'] ?? ($application['email_body'] ?? '')));
        if (!$application || !filter_var($recipient, FILTER_VALIDATE_EMAIL) || $subject === '' || $body === '') {
            flash(tr('flash.applications.mail_required'), 'danger');
            redirect('/?page=applications&edit=' . $id . '#application-form');
        }
        $uid = userId();
        $attachmentState = applicationDocumentAttachmentState($db, $uid, $id);
        $attachments = $attachmentState['files'];
        if ($attachmentState['missing']) {
            flash(tr('applications.attachments_missing', null, ['documents' => implode(', ', $attachmentState['missing'])]), 'danger');
            redirect('/?page=applications&edit=' . $id . '#application-form');
        }
        $sent = false;
        try {
            $sent = sendConfiguredMail($db, $config, $uid, $recipient, $subject, $body, $attachments);
        } catch (Throwable) {
            flash(tr('flash.applications.mail_failed'), 'danger');
            redirect('/?page=applications&edit=' . $id . '#application-form');
        }
        if ($sent) {
            $now = date('Y-m-d H:i:s');
            $sentStatus = 'sent';
            $stmt = $db->prepare("UPDATE applications SET status=?, channel='email', applied_at=COALESCE(applied_at, ?),
                next_action_at=CASE WHEN next_action IN ('send_application','await_response') THEN NULL ELSE next_action_at END,
                next_action=CASE WHEN next_action IN ('send_application','await_response') THEN NULL ELSE next_action END,
                email_subject=?, email_body=? WHERE id=? AND user_id=?");
            $stmt->bind_param('ssssii', $sentStatus, $now, $subject, $body, $id, $uid);
            $stmt->execute();
            $oldStatus = (string) $application['status'];
            if ($oldStatus !== $sentStatus) {
                $history = $db->prepare('INSERT INTO application_status_history (application_id, changed_by, old_status, new_status, comment) VALUES (?, ?, ?, ?, ?)');
                $comment = 'Bewerbungs-E-Mail versendet an ' . $recipient;
                $history->bind_param('iisss', $id, $uid, $oldStatus, $sentStatus, $comment);
                $history->execute();
            }
            audit($db, $uid, 'send', 'outbound_email', $id, null, ['recipient' => $recipient, 'application_id' => $id, 'attachments' => count($attachments)]);
            ensureSubmittedApplicationContactLog($db, $uid, $id);
            ensureSubmittedApplicationCalendarEvent($db, $uid, $id);
            syncCalendarAutomatically($db, $config, $uid, $currentUser ?? []);
            flash(tr('applications.email_sent'));
        } else {
            flash(tr('flash.applications.smtp_missing_draft'), 'warning');
        }
        redirect('/?page=applications&edit=' . $id . '#application-form');
    }

    if ($action === 'delete_application') {
        $id = (int) ($_POST['id'] ?? 0);
        $old = dbOne($db, 'SELECT id, job_id, status, next_action, next_action_at FROM applications WHERE id=? AND user_id=? AND deleted_at IS NULL', 'ii', [$id, userId()]);
        if ($old) {
            $uid = userId();
            cleanupApplicationCascade($db, $uid, $id);
            $stmt = $db->prepare('UPDATE applications SET deleted_at=NOW() WHERE id=? AND user_id=?');
            $stmt->bind_param('ii', $id, $uid);
            $stmt->execute();
            audit($db, $uid, 'delete', 'application', $id, $old, null);
        }
        flash(tr('applications.deleted'));
        redirect('/?page=applications');
    }
}

if ($page === 'two_factor' && !empty($_SESSION['pending_2fa_user_id'])) {
    clearAuthenticatedSession();
}

$currentUser = userId() ? dbOne($db, 'SELECT * FROM users WHERE id = ?', 'i', [userId()]) : null;
$currentUserIsAdmin = $currentUser ? isAdmin($db, realUserId(), $config) : false;
if ($currentUser && isset($_GET['lang'])) {
    $requestedLocale = normalizeLocale((string) $_GET['lang']);
    if ($requestedLocale !== normalizeLocale((string) ($currentUser['preferred_language'] ?? 'de-CH'))) {
        try {
            $stmt = $db->prepare('UPDATE users SET preferred_language=? WHERE id=?');
            $uid = userId();
            $stmt->bind_param('si', $requestedLocale, $uid);
            $stmt->execute();
            $currentUser['preferred_language'] = $requestedLocale;
        } catch (Throwable $exception) {
            error_log('Locale preference update failed: ' . $exception->getMessage());
        }
    }
    $_SESSION['locale'] = $requestedLocale;
}
$appLocale = currentLocale($currentUser ?: null);
if (!pageSupportsMultilingualUi($page)) {
    $appLocale = 'de-CH';
}
$codeVersion = '2.1.6';
$configuredVersion = (string) ($config['app_version'] ?? '');
$appVersion = version_compare($configuredVersion, $codeVersion, '>=') ? $configuredVersion : $codeVersion;
seedDbUiTextCatalog();
if ($currentUser) {
    touchUserPresence($db, realUserId());
    if (realUserId() === userId()) {
        $currentUser['last_seen_at'] = date('Y-m-d H:i:s');
    }
}
if (isSupportImpersonation()) {
    $targetId = (int) ($_SESSION['support_target_user_id'] ?? 0);
    if ($targetId !== userId() || !activeSupportGrant($db, $targetId) || !$currentUser) {
        endSupportImpersonationSession();
        flash(tr('flash.support.ended_inactive_grant'), 'warning');
        redirect('/?page=admin_users');
    }
}
if ($currentUser && in_array($currentUser['timezone'], timezone_identifiers_list(), true)) {
    date_default_timezone_set($currentUser['timezone']);
}
if ($page === 'verify_email') {
    $token = trim((string) ($_GET['token'] ?? ''));
    $reset = null;
    if ($token !== '') {
        $tokenHash = hash('sha256', $token);
        $reset = dbOne(
            $db,
            "SELECT t.id token_id, t.user_id
               FROM auth_tokens t
               JOIN users u ON u.id=t.user_id
              WHERE t.token_type='email_verify'
                AND t.token_hash=?
                AND t.consumed_at IS NULL
                AND t.expires_at > NOW()
                AND u.deleted_at IS NULL
              LIMIT 1",
            's',
            [$tokenHash]
        );
    }
    if ($reset) {
        $stmt = $db->prepare('UPDATE users SET email_verified_at=COALESCE(email_verified_at, NOW()), status="active" WHERE id=?');
        $stmt->bind_param('i', $reset['user_id']);
        $stmt->execute();
        $stmt = $db->prepare('UPDATE auth_tokens SET consumed_at=NOW() WHERE id=?');
        $stmt->bind_param('i', $reset['token_id']);
        $stmt->execute();
        audit($db, (int) $reset['user_id'], 'update', 'user', (int) $reset['user_id'], null, ['email_verified' => true]);
        flash(tr('flash.auth.email_verified'));
    } else {
        flash(tr('flash.auth.verify_link_invalid'), 'danger');
    }
    redirect('/?page=login');
}
