    }
    if ($type === 'companies') {
        $rows = dbAll($db, 'SELECT id, name, city, phone, website, updated_at FROM companies WHERE owner_user_id=? AND deleted_at IS NULL ORDER BY name', 'i', [userId()]);
        pdfResponse('firmen.pdf', tr('nav.companies'), [tr('common.name'),tr('companies.city'),tr('profile.phone'),tr('companies.website'),tr('common.updated')], array_map(static fn(array $r): array => [$r['name'], $r['city'], $r['phone'], $r['website'], $r['updated_at']], $rows));
    }
    if ($type === 'contacts') {
        $rows = dbAll($db, 'SELECT ct.id, ct.first_name, ct.last_name, c.name company_name, ct.email, ct.phone FROM contacts ct JOIN companies c ON c.id=ct.company_id WHERE ct.owner_user_id=? AND ct.deleted_at IS NULL ORDER BY c.name, ct.last_name', 'i', [userId()]);
        pdfResponse('kontakte.pdf', tr('nav.contacts'), [tr('auth.first_name'),tr('auth.last_name'),tr('companies.company'),tr('auth.email'),tr('profile.phone')], array_map(static fn(array $r): array => [$r['first_name'], $r['last_name'], $r['company_name'], $r['email'], $r['phone']], $rows));
    }
    if ($type === 'documents') {
        $rows = dbAll($db, 'SELECT d.id, d.title, dt.code type_code, d.version, d.original_filename, d.file_size, d.created_at FROM user_documents d JOIN document_types dt ON dt.id=d.document_type_id WHERE d.user_id=? AND d.deleted_at IS NULL ORDER BY d.created_at DESC', 'i', [userId()]);
        pdfResponse('dokumente.pdf', tr('nav.documents'), [tr('common.title'),tr('documents.type'),tr('documents.version'),tr('documents.file'),tr('documents.size'),tr('common.date')], array_map(static fn(array $r): array => [$r['title'], documentTypeLabel((string)$r['type_code'], currentLocale($currentUser ?? null)), 'v'.$r['version'], $r['original_filename'], bytesLabel((int)$r['file_size']), $r['created_at']], $rows));
    }
    $jobStatuses = jobStatusOptions();
    $workplaceTypes = workplaceTypeOptions();
    $rows = dbAll($db, 'SELECT j.id, j.title, c.name company, j.location_text, j.status, j.workplace_type, j.created_at, j.updated_at FROM jobs j JOIN companies c ON c.id=j.company_id WHERE j.owner_user_id=? AND j.deleted_at IS NULL ORDER BY j.updated_at DESC', 'i', [userId()]);
    pdfResponse('jobs.pdf', tr('nav.jobs'), [tr('jobs.recorded_at'),tr('common.title'),tr('companies.company'),tr('jobs.location'),tr('common.status'),tr('jobs.workplace_type'),tr('common.updated')], array_map(static fn(array $r): array => [displayDateTime($r['created_at'], $currentUser, false),$r['title'], $r['company'], $r['location_text'], optionLabel($jobStatuses, $r['status']), optionLabel($workplaceTypes, $r['workplace_type']), $r['updated_at']], $rows));
}
if ($page === 'calendar_feed') {
    $token = trim((string) ($_GET['token'] ?? ''));
    $feed = $token !== '' ? dbOne($db, "SELECT f.user_id, u.timezone FROM user_calendar_feeds f JOIN users u ON u.id=f.user_id WHERE f.token=? AND f.is_active=1 AND u.deleted_at IS NULL AND u.status='active' LIMIT 1", 's', [$token]) : null;
    if (!$feed) {
        http_response_code(404);
        header('Content-Type: text/plain; charset=utf-8');
        exit(tr('calendar.feed_not_found'));
    }
    $feedStart = (new DateTimeImmutable('-90 days'))->setTime(0, 0);
    $feedEnd = (new DateTimeImmutable('+365 days'))->setTime(23, 59, 59);
    calendarIcsResponse('jema-jobs-google.ics', calendarEventRows($db, (int) $feed['user_id'], $feedStart, $feedEnd), $feed);
}
if ($page === 'google_calendar_callback') {
    requireLogin();
    $state = (string) ($_GET['state'] ?? '');
    $expectedState = (string) ($_SESSION['google_oauth_state'] ?? '');
    unset($_SESSION['google_oauth_state']);
    unset($_SESSION['google_oauth_return_page']);
    $returnUrl = '/?page=profile#calendar-sync';
    if ($state === '' || $expectedState === '' || !hash_equals($expectedState, $state)) {
        flash(tr('flash.google_calendar.oauth_failed', null, ['error' => 'Invalid state']), 'danger');
        redirect($returnUrl);
    }
    if (isset($_GET['error'])) {
        flash(tr('flash.google_calendar.oauth_failed', null, ['error' => (string) $_GET['error']]), 'danger');
        redirect($returnUrl);
    }
    $code = trim((string) ($_GET['code'] ?? ''));
    $settings = googleCalendarSettings($db, userId());
    $credentials = googleCalendarAppCredentials($config);
    $clientId = $credentials['client_id'];
    $clientSecret = $credentials['client_secret'];
    if ($code === '' || $clientId === '' || $clientSecret === '') {
        flash(tr('flash.google_calendar.credentials_required'), 'danger');
        redirect($returnUrl);
    }
    try {
        $tokens = googleFormRequest([
            'client_id' => $clientId,
            'client_secret' => $clientSecret,
            'code' => $code,
            'redirect_uri' => googleCalendarRedirectUri($config),
            'grant_type' => 'authorization_code',
        ]);
        $accessToken = (string) ($tokens['access_token'] ?? '');
        $refreshToken = (string) ($tokens['refresh_token'] ?? '');
        if ($refreshToken === '') {
            $refreshToken = decryptSecret($config, $settings['refresh_token_encrypted'] ?? null);
        }
        if ($accessToken === '' || $refreshToken === '') {
            throw new RuntimeException('Google token missing');
        }
        $calendarId = trim((string) ($settings['calendar_id'] ?? '')) ?: 'primary';
        $calendarSummary = (string) ($settings['calendar_summary'] ?? '');
        if ($calendarId === 'primary') {
            try {
                $calendar = googleJsonRequest('GET', 'https://www.googleapis.com/calendar/v3/calendars/primary', ['Authorization: Bearer ' . $accessToken]);
                $calendarId = (string) ($calendar['id'] ?? 'primary');
                $calendarSummary = (string) ($calendar['summary'] ?? $calendarSummary);
            } catch (Throwable $ignored) {
                $calendarId = 'primary';
            }
        }
        $encryptedAccess = encryptSecret($config, $accessToken);
        $encryptedRefresh = encryptSecret($config, $refreshToken);
        $expires = date('Y-m-d H:i:s', time() + (int) ($tokens['expires_in'] ?? 3600));
        $syncEnabled = 1;
        $uid = userId();
        $stmt = $db->prepare('UPDATE user_google_calendar_settings SET calendar_id=?, calendar_summary=?, access_token_encrypted=?, refresh_token_encrypted=?, token_expires_at=?, sync_enabled=?, last_error=NULL, updated_at=NOW() WHERE user_id=?');
        $stmt->bind_param('sssssii', $calendarId, $calendarSummary, $encryptedAccess, $encryptedRefresh, $expires, $syncEnabled, $uid);
        $stmt->execute();
        syncGoogleCalendarEvents($db, $config, $uid, $currentUser);
        flash(tr('flash.google_calendar.connected'));
    } catch (Throwable $exception) {
        flash(tr('flash.google_calendar.oauth_failed', null, ['error' => $exception->getMessage()]), 'danger');
    }
    redirect($returnUrl);
}
if ($page === 'export_ics') {
