            <section class="panel"><h2><?= e(tr('applications.assigned_contacts')) ?></h2><div class="contact-list"><?php foreach($contacts as $contact): ?><article class="<?= (int)$applicationEdit['primary_contact_id']===(int)$contact['id']?'is-primary':'' ?> <?= $contactEdit && (int)$contactEdit['id']===(int)$contact['id']?'is-selected':'' ?>"><small><a class="record-link" href="/?page=companies&edit=<?= (int)$contact['company_id'] ?>"><?= e($contact['contact_company_name']) ?></a> · <?= e(tr('companies.company')) ?><?php if((int)$contact['job_id']===(int)$applicationEdit['job_id']): ?> · <?= e(tr('reports.field.job')) ?><?php endif; ?><?php if((int)($contact['application_id'] ?? 0)===(int)$applicationEdit['id']): ?> · <?= e(tr('nav.applications')) ?><?php endif; ?></small><strong><a class="record-link" href="/?page=applications&edit=<?= (int)$applicationEdit['id'] ?>&contact=<?= (int)$contact['id'] ?>#contact-log"><?= e($contact['first_name'].' '.$contact['last_name']) ?></a></strong><span><?= e($contact['position'] ?: $contact['department']) ?></span><?php if($contact['email']): ?><a href="mailto:<?= e($contact['email']) ?>"><?= e($contact['email']) ?></a><?php endif; ?><a class="button" href="/?page=applications&edit=<?= (int)$applicationEdit['id'] ?>&contact=<?= (int)$contact['id'] ?>#contact-log"><?= e(tr('contact_log.title')) ?></a></article><?php endforeach; ?><?php if(!$contacts): ?><p class="empty"><?= e(tr('applications.no_contacts')) ?></p><?php endif; ?></div></section>
            <?php if($contactEdit): ?><section class="panel contact-log contact-log-inline" id="contact-log"><div class="section-head"><div><p class="eyebrow"><?= e(tr('contact_log.title')) ?></p><h2><?= e($contactEdit['first_name'].' '.$contactEdit['last_name']) ?></h2></div></div><?= contactLogFormHtml($editLog, (int)$applicationEdit['id'], (int)$contactEdit['id'], $contactLogChannels, $contactLogStatuses) ?><?= contactLogTimelineHtml($contactLogs, $contactAttachments, $contactLogChannels, $contactLogStatuses, $currentUser, (int)$applicationEdit['id']) ?></section><?php endif; ?>
        </section>
        <?php endif; ?>
        <?php if($applicationEdit): ?><?= mailActivityFormHtml($db, userId(), $currentUser, 'application', (int)$applicationEdit['id']) ?><?php endif; ?>
        <?php if($appView === 'table'): ?><section class="panel table-wrap"><table><thead><tr><?= sfHeader('applications','latest_workflow_at',tr('applications.workflow_date'),$appSf,$appPreserve) ?><?= sfHeader('applications','title',tr('reports.field.job'),$appSf,$appPreserve) ?><?= sfHeader('applications','company',tr('companies.company'),$appSf,$appPreserve) ?><?= sfHeader('applications','status',tr('common.status'),$appSf,$appPreserve) ?><?= sfHeader('applications','channel',tr('applications.channel'),$appSf,$appPreserve) ?><th><?= e(tr('common.actions')) ?></th></tr></thead><tbody><?php foreach($apps as $app): $workflow = applicationWorkflowView($app); ?><tr class="<?= $applicationEdit && (int)$applicationEdit['id']===(int)$app['id']?'is-selected':'' ?>"><td><?= e(displayDateTime($workflow['date'], $currentUser, false)) ?></td><td><strong><a href="/?page=applications&edit=<?= (int)$app['id'] ?>#application-form"><?= e($app['title']) ?></a></strong></td><td><a href="/?page=companies&edit=<?= (int)$app['company_id'] ?>"><?= e($app['company_name']) ?></a><?php if($app['intermediary_company_name']): ?><small><?= e(tr('companies.by')) ?> <?= e($app['intermediary_company_name']) ?></small><?php endif; ?></td><td><?= e($applicationStatuses[$app['status']] ?? $app['status']) ?></td><td><?= e(applicationChannelOptions()[(string)$app['channel']] ?? (string)$app['channel']) ?></td><td class="actions"><a href="/?page=applications&edit=<?= (int)$app['id'] ?>#application-form"><?= e(tr('common.edit')) ?></a><form method="post" onsubmit="return confirm('<?= e(tr('applications.delete_confirm')) ?>')"><input type="hidden" name="csrf" value="<?= csrfToken() ?>"><input type="hidden" name="id" value="<?= (int)$app['id'] ?>"><button name="action" value="delete_application"><?= e(tr('common.delete')) ?></button></form></td></tr><?php endforeach; ?><?php if(!$apps): ?><tr><td colspan="6" class="empty"><?= e(tr('common.no_results')) ?></td></tr><?php endif; ?></tbody></table></section><?php else: ?><section class="application-list"><?php foreach($apps as $app): $workflow = applicationWorkflowView($app); $nextActionLabel = $workflow['next_task']; ?><article class="application-card <?= $applicationEdit && (int)$applicationEdit['id']===(int)$app['id']?'is-selected':'' ?>"><p class="meta-line"><?= e(tr('applications.workflow_date')) ?>: <?= e(displayDateTime($workflow['date'], $currentUser, false)) ?></p><div class="job-top"><span class="badge"><?= e($applicationStatuses[$app['status']] ?? $app['status']) ?></span></div><h3><a href="/?page=jobs&edit=<?= (int)$app['job_id'] ?>#new"><?= e($app['title']) ?></a></h3><p class="company"><a href="/?page=companies&edit=<?= (int)$app['company_id'] ?>"><?= e($app['company_name']) ?></a><?php if($app['intermediary_company_name']): ?> · <?= e(tr('companies.by')) ?> <a href="/?page=companies&edit=<?= (int)$app['intermediary_company_id'] ?>"><?= e($app['intermediary_company_name']) ?></a><?php endif; ?></p><?php if($nextActionLabel !== ''): ?><p><strong><?= e(tr('applications.next_task')) ?>:</strong> <?= e($nextActionLabel) ?></p><?php endif; ?><div class="actions"><a href="/?page=applications&edit=<?= (int)$app['id'] ?>#application-form"><?= e(tr('common.edit')) ?></a><form method="post" onsubmit="return confirm('<?= e(tr('applications.delete_confirm')) ?>')"><input type="hidden" name="csrf" value="<?= csrfToken() ?>"><input type="hidden" name="id" value="<?= (int)$app['id'] ?>"><button name="action" value="delete_application"><?= e(tr('common.delete')) ?></button></form></div></article><?php endforeach; ?><?php if(!$apps): ?><div class="panel empty"><h2><?= e(tr('applications.empty_title')) ?></h2><p><?= e(tr('applications.empty_hint')) ?></p><a class="button primary" href="/?page=jobs"><?= e(tr('applications.to_jobs')) ?></a></div><?php endif; ?></section><?php endif; ?>
    <?php elseif ($page === 'contacts'): ?>
        <?php
        $contactCompanyFilter=(int)($_GET['company_id'] ?? 0);
        $contactSfFields = ['name'=>['label'=>tr('contacts.contact'),'expr'=>'CONCAT(ct.last_name, " ", ct.first_name)'], 'company'=>['label'=>tr('companies.company'),'expr'=>'c.name'], 'reachable'=>['label'=>tr('contacts.reachable'),'expr'=>'CONCAT_WS(" ", ct.email, ct.phone, ct.mobile)'], 'crm'=>['label'=>tr('contacts.activity_links'),'expr'=>'CONCAT_WS(" ", j.title, a.status)']];
        $contactSf = sfState('contacts', $contactSfFields, ['sort'=>'name','dir'=>'asc']);
        $contactPreserve = ['page'=>'contacts', 'company_id'=>$contactCompanyFilter ?: '', 'edit_contact'=>$_GET['edit_contact'] ?? ''];
        $contactCompany=$contactCompanyFilter ? dbOne($db,'SELECT id,name FROM companies WHERE id=? AND owner_user_id=? AND deleted_at IS NULL','ii',[$contactCompanyFilter,userId()]) : null;
        $contactEditId=(int)($_GET['edit_contact'] ?? 0);
        $contactEdit=$contactEditId>0 ? dbOne($db,'SELECT id, company_id, first_name, last_name, position, department, email, phone, mobile, linkedin_url, preferred_language, notes FROM contacts WHERE id=? AND owner_user_id=? AND deleted_at IS NULL','ii',[$contactEditId,userId()]) : null;
        $contactLogStatuses=contactLogStatusOptions();
        $contactLogChannels=contactLogChannelOptions();
        $contactLogs=$contactEdit ? dbAll($db,'SELECT id, contact_id, application_id, channel, direction, status, subject, SUBSTRING(body,1,65535) body, occurred_at, follow_up_at, outcome FROM contact_logs WHERE owner_user_id=? AND contact_id=? ORDER BY CASE status WHEN "open" THEN 1 WHEN "planned" THEN 2 WHEN "done" THEN 3 ELSE 4 END, COALESCE(follow_up_at, occurred_at) ASC','ii',[userId(),(int)$contactEdit['id']]) : [];
        $contactAttachments=$contactEdit ? contactLogAttachments($db, userId(), (int)$contactEdit['id']) : [];
        $editLogId=(int)($_GET['edit_log'] ?? 0);
        $editLog=$editLogId > 0 ? dbOne($db,'SELECT id, contact_id, application_id, channel, direction, status, subject, SUBSTRING(body,1,65535) body, occurred_at, follow_up_at, outcome FROM contact_logs WHERE id=? AND owner_user_id=? AND contact_id=?','iii',[$editLogId,userId(),(int)($contactEdit['id'] ?? 0)]) : null;
        $contactSql='SELECT ct.*, c.name company_name, j.title job_title, a.status application_status, (SELECT COUNT(*) FROM contact_logs l WHERE l.contact_id=ct.id AND l.owner_user_id=ct.owner_user_id) log_count, (SELECT COUNT(*) FROM contact_logs l WHERE l.contact_id=ct.id AND l.owner_user_id=ct.owner_user_id AND l.status IN ("planned","open")) open_log_count FROM contacts ct JOIN companies c ON c.id=ct.company_id LEFT JOIN jobs j ON j.id=ct.job_id LEFT JOIN applications a ON a.id=ct.application_id WHERE ct.owner_user_id=? AND ct.deleted_at IS NULL'; $contactTypes='i'; $contactVals=[userId()];
        if($contactCompanyFilter>0){ $contactSql.=' AND ct.company_id=?'; $contactTypes.='i'; $contactVals[]=$contactCompanyFilter; }
        $contactSql .= sfApplySql($contactSf, $contactSfFields, $contactTypes, $contactVals);
        $contactOrder = sfOrderSql($contactSf, $contactSfFields, 'name');
        $contactSql .= $contactOrder !== '' ? $contactOrder . ', ct.first_name' : ' ORDER BY ct.last_name, ct.first_name';
        $contactRows=dbAll($db,$contactSql,$contactTypes,$contactVals);
        ?>
        <?php
        $newContact = !$contactEdit && !empty($_GET['new_contact']);
        $contactForm = $contactEdit ?: array_fill_keys(['id','first_name','last_name','position','department','email','phone','mobile','linkedin_url','preferred_language','notes'], '');
        $contactForm['company_id'] = $contactEdit['company_id'] ?? ($contactCompany['id'] ?? 0);
        ?>
        <?php if($newContact && !$companies): ?><div class="actions"><a class="button" href="/?page=companies#new"><?= e(tr('jobs.new_company')) ?></a></div><?php endif; ?>
        <div class="page-head"><div><p class="eyebrow"><?= e(tr('nav.crm')) ?></p><h1><?= e(tr('contacts.title')) ?></h1></div><span><?= e(tr('common.entries_count', null, ['count' => (string) count($contactRows)])) ?></span><a class="button primary" href="/?page=contacts&new_contact=1<?= $contactCompany ? '&company_id=' . (int)$contactCompany['id'] : '' ?>#contact-editor"><?= e(tr('contacts.create')) ?></a></div>
        <div class="actions export-actions"><?= sfToolbar('contacts', $contactSf, ['page'=>'contacts', 'company_id'=>$contactCompanyFilter ?: ''], $contactSfFields) ?><a class="button" href="/?page=export_pdf&type=contacts">PDF</a></div>
        <?php if($contactCompany): ?><p class="filter-note"><?= e(tr('contacts.at_company')) ?> <a href="/?page=companies&edit=<?= (int)$contactCompany['id'] ?>"><?= e($contactCompany['name']) ?></a> · <a href="/?page=contacts"><?= e(tr('contacts.show_all')) ?></a></p><?php endif; ?>
        <div class="<?= ($contactEdit || $newContact) ? 'split' : 'full-width' ?>"><?php if($contactEdit || $newContact): ?><section class="panel" id="contact-editor"><h2><?= e(tr($contactEdit ? 'contacts.edit' : 'contacts.create')) ?></h2><form method="post" class="stack"><input type="hidden" name="csrf" value="<?= csrfToken() ?>"><input type="hidden" name="contact_id" value="<?= (int)$contactForm['id'] ?>"><label><?= e(tr('companies.company')) ?><select name="contact_company_id"><?php foreach($companies as $company): ?><option value="<?= (int)$company['id'] ?>" <?= (int)$contactForm['company_id']===(int)$company['id']?'selected':'' ?>><?= e($company['name']) ?></option><?php endforeach; ?></select></label><div class="two"><label><?= e(tr('auth.first_name')) ?><input name="first_name" value="<?= e($contactForm['first_name']) ?>" required></label><label><?= e(tr('auth.last_name')) ?><input name="last_name" value="<?= e($contactForm['last_name']) ?>" required></label></div><div class="two"><label><?= e(tr('contacts.position')) ?><input name="position" value="<?= e($contactForm['position']) ?>"></label><label><?= e(tr('contacts.department')) ?><input name="department" value="<?= e($contactForm['department']) ?>"></label></div><label><?= e(tr('auth.email')) ?><input type="email" name="contact_email" value="<?= e($contactForm['email']) ?>"></label><div class="two"><label><?= e(tr('profile.phone')) ?><input name="phone" value="<?= e($contactForm['phone']) ?>"></label><label><?= e(tr('profile.mobile')) ?><input name="mobile" value="<?= e($contactForm['mobile']) ?>"></label></div><label>LinkedIn<input type="url" name="linkedin_url" value="<?= e($contactForm['linkedin_url']) ?>"></label><label><?= e(tr('profile.language_label')) ?><select name="preferred_language"><option value=""><?= e(tr('common.not_selected')) ?></option><?php foreach(documentLanguageChoices() as $v=>$l): ?><option value="<?= e($v) ?>" <?= ($contactForm['preferred_language']??'')===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select></label><label><?= e(tr('common.comment')) ?><textarea name="contact_notes" rows="4"><?= e($contactForm['notes']) ?></textarea></label><div class="actions"><button class="primary" name="action" value="<?= $newContact ? 'create_contact_global' : 'update_contact_global' ?>"><?= e(tr('contacts.save_contact')) ?></button><a class="button" href="/?page=contacts"><?= e(tr('common.close')) ?></a></div></form><?php if($contactEdit): ?><hr><h2 id="contact-log"><?= e(tr('contact_log.title')) ?></h2><?= contactLogFormHtml($editLog, 0, (int)$contactEdit['id'], $contactLogChannels, $contactLogStatuses) ?><?= contactLogTimelineHtml($contactLogs, $contactAttachments, $contactLogChannels, $contactLogStatuses, $currentUser) ?><?php endif; ?></section><?php endif; ?><section class="panel table-wrap"><table><thead><tr><?= sfHeader('contacts','name',tr('contacts.contact'),$contactSf,$contactPreserve) ?><?= sfHeader('contacts','company',tr('companies.company'),$contactSf,$contactPreserve) ?><?= sfHeader('contacts','reachable',tr('contacts.reachable'),$contactSf,$contactPreserve) ?><?= sfHeader('contacts','crm',tr('contacts.activity_links'),$contactSf,$contactPreserve) ?><th><?= e(tr('common.actions')) ?></th></tr></thead><tbody><?php foreach($contactRows as $contact): ?><tr class="<?= $contactEdit && (int)$contactEdit['id']===(int)$contact['id']?'is-selected':'' ?>"><td><strong><?= e($contact['first_name'].' '.$contact['last_name']) ?></strong><small><?= e($contact['position'] ?: $contact['department']) ?></small></td><td><a href="/?page=companies&edit=<?= (int)$contact['company_id'] ?>"><?= e($contact['company_name']) ?></a></td><td><?php if($contact['email']): ?><a href="mailto:<?= e($contact['email']) ?>"><?= e($contact['email']) ?></a><?php endif; ?><small><?= e($contact['phone'] ?: $contact['mobile']) ?></small></td><td class="contact-activity-links"><div><?= e(tr('contacts.activity_counts', null, ['open' => (string)(int)$contact['open_log_count'], 'total' => (string)(int)$contact['log_count']])) ?></div><?php if($contact['job_id']): ?><div><a href="/?page=jobs&edit=<?= (int)$contact['job_id'] ?>#new"><?= e($contact['job_title'] ?: tr('contacts.open_job')) ?></a></div><?php endif; ?><?php if($contact['application_id']): ?><div><a href="/?page=applications&edit=<?= (int)$contact['application_id'] ?>&contact=<?= (int)$contact['id'] ?>#contact-log"><?= e(tr('contacts.application_activities')) ?></a></div><?php endif; ?></td><td class="actions"><a href="/?page=contacts&edit_contact=<?= (int)$contact['id'] ?>"><?= e(tr('common.edit')) ?></a><a href="/?page=contacts&edit_contact=<?= (int)$contact['id'] ?>#contact-log"><?= e(tr('contacts.new_entry')) ?></a><form method="post" onsubmit="return confirm('<?= e(tr('bulk.delete_confirm')) ?>')"><input type="hidden" name="csrf" value="<?= csrfToken() ?>"><input type="hidden" name="contact_id" value="<?= (int)$contact['id'] ?>"><button name="action" value="delete_contact"><?= e(tr('common.delete')) ?></button></form></td></tr><?php endforeach; ?><?php if(!$contactRows): ?><tr><td colspan="5" class="empty"><?= e(tr('contacts.empty')) ?></td></tr><?php endif; ?></tbody></table></section></div>
        <?php if($contactEdit): ?><?= mailActivityFormHtml($db, userId(), $currentUser, 'contact', (int)$contactEdit['id']) ?><?php endif; ?>
    <?php elseif ($page === 'documents'): ?>
        <?php
        $documentTypes = dbAll($db, 'SELECT id, code, name_key FROM document_types ORDER BY id');
        $profileDocumentTypes = documentTypesForScope($documentTypes, 'profile');
        $userLanguage = normalizeLocale((string) ($currentUser['preferred_language'] ?? 'de-CH'));
        $documentTypeChoices = [];
        foreach ($profileDocumentTypes as $type) {
            $documentTypeChoices[(string)$type['code']] = documentTypeLabel((string)$type['code'], $userLanguage);
        }
        $docSfFields = [
            'title'=>['label'=>tr('documents.document'),'expr'=>'d.title'],
            'type'=>['label'=>tr('documents.type'),'expr'=>'dt.code', 'choices'=>$documentTypeChoices],
            'language'=>['label'=>tr('profile.language_label'),'expr'=>'d.language_code','choices'=>documentLanguageChoices()],
            'version'=>['label'=>tr('documents.version'),'expr'=>'CAST(d.version AS CHAR)'],
            'created_at'=>['label'=>tr('common.date'),'expr'=>'d.created_at'],
        ];
        $docSf = sfState('documents', $docSfFields, ['sort'=>'created_at','dir'=>'desc']);
        $docPreserve = ['page'=>'documents'];
        $docSql="SELECT d.*, dt.code type_code, dt.name_key type_name FROM user_documents d JOIN document_types dt ON dt.id=d.document_type_id WHERE d.user_id=? AND d.scope='profile' AND d.deleted_at IS NULL"; $docTypes='i'; $docVals=[userId()];
        $docSql .= sfApplySql($docSf, $docSfFields, $docTypes, $docVals);
        $docOrder = sfOrderSql($docSf, $docSfFields, 'created_at');
        $docSql .= $docOrder !== '' ? $docOrder . ', d.title' : ' ORDER BY d.created_at DESC, d.title';
        $documents = dbAll($db, $docSql, $docTypes, $docVals);
        $editDocumentId = (int) ($_GET['edit_document'] ?? 0);
        $editDocument = $editDocumentId > 0 ? dbOne($db, "SELECT d.*, dt.code type_code FROM user_documents d JOIN document_types dt ON dt.id=d.document_type_id WHERE d.id=? AND d.user_id=? AND d.scope='profile' AND d.deleted_at IS NULL", 'ii', [$editDocumentId, userId()]) : null;
        ?>
        <div class="page-head"><div><p class="eyebrow"><?= e(tr('profile.master_data')) ?></p><h1><?= e(tr('documents.title')) ?></h1></div><span><?= count($documents) ?> <?= e(tr('common.versions')) ?></span></div>
        <div class="actions export-actions"><?= sfToolbar('documents', $docSf, $docPreserve, $docSfFields) ?><a class="button" href="/?page=export_pdf&type=documents">PDF</a></div>
        <div class="split"><section class="panel" id="document-editor"><h2><?= e($editDocument ? tr('documents.edit_document') : tr('documents.upload_document')) ?></h2><form method="post" enctype="multipart/form-data" class="stack"><input type="hidden" name="csrf" value="<?= csrfToken() ?>"><input type="hidden" name="document_return" value="documents"><input type="hidden" name="document_scope" value="profile"><?php if($editDocument): ?><input type="hidden" name="document_id" value="<?= (int)$editDocument['id'] ?>"><?php else: ?><label><?= e(tr('documents.new_version_of')) ?><select name="replace_document_id"><option value="0"><?= e(tr('documents.new_document')) ?></option><?php foreach($documents as $doc): if(!(int)$doc['is_current']) continue; ?><option value="<?= (int)$doc['id'] ?>"><?= e($doc['title']) ?> · v<?= (int)$doc['version'] ?></option><?php endforeach; ?></select></label><?php endif; ?><label><?= e(tr('documents.document_type')) ?><select name="document_type_id"><?php foreach($profileDocumentTypes as $type): ?><option value="<?= (int)$type['id'] ?>" <?= (int)($editDocument['document_type_id'] ?? 0)===(int)$type['id']?'selected':'' ?>><?= e(documentTypeLabel((string)$type['code'], $userLanguage)) ?></option><?php endforeach; ?></select></label><label><?= e(tr('common.title')) ?><input name="document_title" required placeholder="<?= e(tr('documents.title_placeholder_profile')) ?>" value="<?= e($editDocument['title'] ?? '') ?>"></label><label><?= e(tr('profile.language_label')) ?><select name="document_language"><option value=""><?= e(tr('common.not_selected')) ?></option><?php foreach(documentLanguageChoices() as $v=>$l): ?><option value="<?= e($v) ?>" <?= (string)($editDocument['language_code'] ?? $userLanguage)===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select></label><div class="two"><label><?= e(tr('documents.valid_from')) ?><input type="date" name="valid_from" value="<?= e($editDocument['valid_from'] ?? '') ?>"></label><label><?= e(tr('documents.valid_until')) ?><input type="date" name="valid_until" value="<?= e($editDocument['valid_until'] ?? '') ?>"></label></div><label><?= e(tr('common.description')) ?><textarea name="document_description" rows="3"><?= e($editDocument['description'] ?? '') ?></textarea></label><?php if($editDocument): ?><div class="actions"><button class="primary" name="action" value="update_document"><?= e(tr('common.save_changes')) ?></button><a class="button" href="/?page=documents"><?= e(tr('documents.upload_new')) ?></a><a class="button" href="/?page=document_download&id=<?= (int)$editDocument['id'] ?>"><?= e(tr('common.download')) ?></a></div><p class="meta-line"><?= e(tr('documents.replace_file_hint')) ?></p><?php else: ?><?= filePickerHtml('user_document') ?><button class="primary" name="action" value="upload_document"><?= e(tr('common.save')) ?></button><?php endif; ?></form></section>
